quests[25996] = { id = 25996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Beast", description = "Thanks to you and the Legionnaire, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", sourceObjective = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank Hellscream that you found me before you and your shaman activated those bio-defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25997] = { id = 25997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Scheming", description = "A cadre of Dark Iron spies have taken over Ironband's Compound to the south, beyond Helm's Bed Lake. The mountaineers are normally able to keep them from getting into Dun Morogh, but everything is in disarray right now.\n\nThe Dark Iron dwarves would be fools if they didn't take advantage of the chaos. We have to find out what they're planning and stop them before they do any damage.\n\nWill you see if you can discover what they're doing down at Ironband's Compound?", sourceObjective = "Kill 5 Dark Iron Spies and capture the Dark Iron Attack Plans from Captain Beld at Ironband's Compound.", progress = "What are the Dark Irons up to?", completion = "I knew they weren't here to see the sights.\n\n<The sergeant examines the plans you captured, his eyes wide.>\n\nThis is more serious than we thought! This is no mere raid. The Dark Irons intend to cripple the defense of Ironforge itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[25998] = { id = 25998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to the Airfield", description = "According to the plans you captured, the Dark Irons are planning a large-scale attack on the Ironforge Airfield! The council has moved most of our forces down into Dun Morogh to deal with the instability brought by the cataclysm, leaving our defenses weakened at the airfield.\n\nWe need a way to get you to the airfield quickly. Take the road back west toward Gol'Bolar Quarry and find Mathel Rustwrench. He should have a flying machine you can use. Go!", sourceObjective = "Board Mathel's Flying Machine at the Gol'Bolar Quarry.", completion = "Thank goodness you're here, {name}. The airfield's been attacked by the Dark Irons and I don't think we can hold out much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25999] = { id = 25999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrier to Entry", description = "Filthy, good-for-nothin' night elves have managed to disarm our entire minefield in Talondeep Pass. Somebody is gonna have to go back up there and re-arm them all! A perfect task for a worthless grunt like you, {name}. Here's to hopin' you don't blow yourself up in the process.\n\nYou'll find our \"Elf Killers\" scattered across Talondeep Pass, directly north of here. Take this wrench and get to work, maggot.", sourceObjective = "Arm 8 Krom'gar \"Elf Killers.\"", progress = "What do you have to report, grunt?", completion = "<Saurboz looks you over.>\n\nYou have all of your limbs intact. This is a first.", sourceObjectiveStatus = "unverified-source-field" }
quests[26000] = { id = 26000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", sourceObjective = "Speak to Gurrok in Deepmist Grotto.", completion = "...{race}? Here?\n\nI must be mad...", sourceObjectiveStatus = "unverified-source-field" }
quests[26001] = { id = 26001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Blastgineer", description = "It looks like you might not be completely useless after all. Perhaps you can handle something a little more important.\n\nAbout two days ago I sent Blastgineer Fuzzwhistle to Windshear Mine. He was supposed to get there, make sure everything was going according to plan with the bomb, and report back. Two days and nothin'...\n\nHead out to the woods south of here and find him. For his sake, he better be dead.", sourceObjective = "Find Blastgineer Fuzzwhistle.", completion = "Blastgineer Fuzzwhistle is definitely dead. It's probably for the best.\n\nIt looks like he's holding a note in his hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26002] = { id = 26002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Attack Plans", description = "<You pry the note loose from Fuzzwhistle's hand.>\n\nThey're onto us! They know all about the bomb. Planning an attack on Krom'gar Fortress! I think they sent a search party after me. Won't go out like a chump. They'll get a fight.\n\nI think I hear them coming now! Their leader is a high elf huntress named Davinia. She spoke of attack plans. Avenge me by killing her and getting those plans! Her tent is nearby, to the east.\n\nHellscream's eyes are upon you...", sourceObjective = "Recover the Alliance Attack Plans from Huntress Davinia.", progress = "Did you find Fuzzwhistle?", completion = "Damn shame... He was a good goblin.\n\n<Saurboz shakes his fist.>\n\nAs for you, {name}, you've done well. These attack plans will help us prepare. I want you to deliver the plans to Overlord Krom'gar personally! There's sure to be a promotion in it for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26003] = { id = 26003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons from the Lost Isles", description = "There are great dangers in the woods south of here. They are crawling with Darnassian scouts - assassins sent from Darnassus to kill us. Perhaps we can turn the tables on them, eh?\n\nWhen I was marooned on the Lost Isles a goblin gave me these infrared heat focals. They allow the wearer to see heat signatures of certain creatures. Take the focals and use them while in the woods to the south. They will allow you to easily spot the scouts. Kill as many of them as you can! For the Horde!", sourceObjective = "Kill 12 Darnassian Scouts.", completion = "Well done, brother! Now they will know that they cannot sneak up on the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26004] = { id = 26004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krom'gar Fortress", description = "Our main base of operations in Stonetalon Mountains is Krom'gar Fortress. It is from there that Overlord Krom'gar oversees all Horde military activity in the region. Krom'gar reports everything that happens directly to the Warchief.\n\nThe attack plans you brought back detail an assault that's supposed to take place against Krom'gar Fortress soon. Take the plans and head to the fortress, southwest of here. Give them to the Overlord.\n\nSo long, {name}. Truly, Hellscream's eyes are upon you.", sourceObjective = "Deliver the Alliance Attack Plans to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "What is the meaning of this interruption? Why does this grunt stand before Overlord Krom'gar?", completion = "<Overlord Krom'gar takes the plans from you.>\n\nHmm. Perhaps this grunt is more than he would appear. Perhaps this grunt is in actuality a sergeant.\n\nLook now upon Krom'gar Sergeant {name}, soldiers. He has come to serve warning of a cowardly Alliance attack. An attack that we will CRUSH!", sourceObjectiveStatus = "unverified-source-field" }
quests[26005] = { id = 26005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Breath of Fresh Air", description = "Captain Taylor and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nHexascrub left these behind for you. They should speed your trip up a bit.", sourceObjective = "Find Captain Taylor aboard Voldrin's Hold, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "You made it out! Good to see you, {name}.\n\nIt's good to be out of the water for a bit, and to have some resources at our disposal again. I'm sure many of the boys would give anything to turn around and head home after what we've been through, but we still have a grim task ahead.\n\nWhat about you? Want to stick it through to the end with us? I wouldn't blame you if you've had your fill.", sourceObjectiveStatus = "unverified-source-field" }
quests[26006] = { id = 26006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Breath of Fresh Air", description = "Legionnaire Nazgrim and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nFiasco left these behind for you. They should speed your trip up a bit.", sourceObjective = "Find Legionnaire Nazgrim aboard the Stygian Bounty, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "Looks like you make it out in one piece, {class}!\n\nIt's good to be out of that foul pit of water for a moment, and to have some resources at our disposal again. Don't get too comfortable though, we still have a grim task ahead.\n\nWhat about you? Had enough honor for one day, or do you want to get back in there and make Hellscream proud?", sourceObjectiveStatus = "unverified-source-field" }
quests[26007] = { id = 26007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debriefing", description = "This warrior was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", sourceObjective = "Speak with Gurrok and learn about his ordeal.", progress = "That's it, {race}.\n\nThat's all I know...", completion = "Well, it's not encouraging, but it's something...", sourceObjectiveStatus = "unverified-source-field" }
quests[26008] = { id = 26008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decompression", description = "I simply cannot bear the thought of so many others like this warrior imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", sourceObjective = "Use Moanah's Breathstone on 10 Imprisoned Warriors in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[26009] = { id = 26009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek and Destroy", description = "The Alliance encroaches upon our territories within Stonetalon. The forces of Northwatch have broken through our blockade in the south and occupy Windshear Valley, to our west. From the northern front comes an onslaught of night elf soldiers. All must be stopped!\n\nVenture forth into Stonetalon and destroy all Alliance soldiers that cross your path. Let their deaths serve as a message.\n\nStonetalon belongs to the Horde!", sourceObjective = "Slay any 20 soldiers of the Alliance in Stonetalon Mountains.", completion = "Much more blood shall be spilled upon this soil before this war is over. Alliance blood...", sourceObjectiveStatus = "unverified-source-field" }
quests[26010] = { id = 26010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "The Alliance have grown bold. Just west of here, in Windshear Valley, Northwatch troops have set up camp. No doubt they are preparing for the assault you warned us of, {name}. They will never get the chance!\n\nTake this flame thrower. It is the same flame thrower my incinerators use to burn our enemies out of hiding in the forests. Use it to destroy the Northwatch tents. Leave only ashes in your wake!", sourceObjective = "Use the Krom'gar Flamethrower to destroy 8 Northwatch Tents.", completion = "Lok'tar! Alliance pigs!\n\n<Overlord Krom'gar spits on the ground.>\n\nEnjoy the victory for it shall be short lived. Your bravery has given us more time to prepare, nothing more.", sourceObjectiveStatus = "unverified-source-field" }
quests[26011] = { id = 26011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy of the Horde: Marshal Paltrow", description = "My scouts have tracked the cause of this latest fiasco to one man: Marshal Paltrow. He commands the Northwatch forward camp that has established itself in Windshear Valley, west of here. Take him out and you remove a powerful Alliance field commander from the equation.\n\nPaltrow must die, {name}.", sourceObjective = "Kill Marshal Paltrow.", completion = "Did you find any suspicious documents at Paltrow's camp? Perhaps on his rotting corpse? Any insight into the Alliance's attack patterns would be extremely helpful in the battle for Stonetalon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Wyrmrest", description = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.\n\nPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", sourceObjective = "Speak with Krasus at Wyrmrest Temple in Dragonblight.", completion = "Thank you for heeding Rhonin's call, brave adventurer.\n\nLet me share with you what we know regarding recent events, and any assistance you might offer would be greatly appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Sanctum", description = "{race}, something terrible has transpired within the Ruby Sanctum beneath the Temple.\n\nThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.\n\nEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", sourceObjective = "Investigate the Ruby Sanctum beneath Wyrmrest Temple.", completion = "Thank you again, {class}, for rescuing me from Baltharus's clutches!\n\nThere is still much work to be done, however....", sourceObjectiveStatus = "unverified-source-field" }
quests[26014] = { id = 26014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Digsong", description = "Private {name}, at attention!  Ve are havink a small problem!\n\nVe have sent Humphrey and Oskar Digsong out to Underlight Canyon, to the northvest, but they are not comink back.  They vere supposed to scout out the area, but ve have lost all contact with them.\n\nYour assignment, Private {name}, is to locate our comrades and, if they live, bring them back to me!", sourceObjective = "Report to Humphrey Digsong at Underlight Canyon in Vashj'ir.", completion = "Of course we haven't returned yet!  We've had our fair share of setbacks... not the least of which was the passing of my dear brother Oskar.\n\n<Humphrey sniffles loudly.>\n\nHe lost his grip and floated away, the poor lad!  He thought he'd grab some fish to bring back to the captain, but he floated off, and was eaten by one o' those... those great-eels!  Bwaaaah ha ha haaaah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26015] = { id = 26015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phosphora Hunting", description = "Oskar's last wish, before he floated up into that great-eel's gullet, was to bring back food for the captain, so that's what we'll do.\n\nMy brother had a genius plan.  He saw those murlocs luring fish out of the reeds with a phosphorescent antenna, and devised a way to make one of his own.  All ya need is something that glows.\n\nKill the crabs and groupers that roam the canyon's floor.  They aren't edible themselves, but their phosphora is far more valuable than their meat.", sourceObjective = "Obtain 6 Underlight Phosphora from Pyreshell Scuttlers and Luxscale Groupers in Underlight Canyon.", progress = "We need enough phosphora to make a really bright light, especially if you're going to be competing with those murlocs.", completion = "<Humphrey grabs the phosphora from you and attaches it to an unusual device.>\n\nThere ya go.  It's beautiful!  Oskar would be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26016] = { id = 26016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Base Camp", description = "Paltrow, establish a foothold in Windshear Valley. A strong ground assault is vital to our campaign! When we make our assault against Krom'gar, your men will provide the chaos and confusion that the gnome flying machines will need to get close enough to bomb the orc fortress.\n\nThe flying machines will detonate the Krom'gar bomb while it's sitting in their base, taking out the entire fortress in the process.\n\nBurn after reading.\n\n-Force Commander Valen\n\nNorthwatch Expedition Base Camp", sourceObjective = "Deliver the Orders from Base Camp to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "More gnomes?", completion = "Gnomish flying machines? Our anti-air cannons are still not functional! We will be sitting ducks.\n\nI require time to plan... to think...\n\nThe hot air balloon and its payload cannot remain at Krom'gar Fortress. I must make arrangements to move the balloon to another location. Our plans to destroy Windshear Hold with it are foiled.", sourceObjectiveStatus = "unverified-source-field" }
quests[26017] = { id = 26017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lure", description = "Stick this device on your head, then swim through the kelp and coral along the canyon's edge.  There should be all kinds of little fish in there that find your new antenna irresistible.\n\nWhen we return to Darkbreak Cove, we'll have armfuls of fish for everyone!", sourceObjective = "Put on the Phosphora Fedora, then swim through the coral in Underlight Canyon to attract 30 Underlight Nibblers.", progress = "How many did ya catch?", completion = "Ya did good, {name}!  Ya did real good!", sourceObjectiveStatus = "unverified-source-field" }
quests[26018] = { id = 26018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldlights Out", description = "Oh yeah!  I was supposed to put together a report!  I'd almost forgotten!\n\nLooks like mostly harmless wildlife around here... 'cept for those blasted eels... and a few murlocs.  Cap'n will be more interested in the murlocs, I think.\n\nGo engage a few of 'em in combat and see what kinda moves they got.  From what I've seen, the big ones hunt for fish in the kelp, and the little ones practice some kind o' magic or another... but that's all I know.", sourceObjective = "Kill 4 Coldlight Hunters and 4 Coldlight Oracles.", completion = "<Humphrey listens as you recount your fights with the Coldlight murlocs.>\n\nHmm... they sound like regular ol' murlocs... just underwater.  That'll make Cap'n Glovaal happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[26019] = { id = 26019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormous Eel Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Humphrey might be interested in something like this.>", sourceObjective = "Deliver the Enormous Eel Egg to Humphrey Digsong at the bottom of Underlight Canyon in Vashj'ir.", progress = "What've ya got there, {name}?", completion = "Whaaa... an egg?  An EEL egg?\n\n<Even upside-down, you can see the gears in Humphrey's head turning.>\n\nWe can definitely do something with this!  Get ready kid, 'cause it's time for some good ol'-fashioned Digsong revenge!", sourceObjectiveStatus = "unverified-source-field" }
quests[26020] = { id = 26020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Bombgutz", description = "We must prepare for the impending attack. I will have our soldiers prepare the bomb for transport. I want you to report to Chief Blastgineer Bombgutz. She has been working to fix our anti-air cannons, but has thus far failed. Make sure that she is properly motivated to repair our guns, {name}.", sourceObjective = "Report to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", completion = "Properly motivated? Wha... what does that mean? Listen, Sergeant, I have a built in mechanism for survival called self-interest. That is, it's in my best interest to NOT DIE. With that said, there's no fixing these guns without the right materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[26021] = { id = 26021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Digsong 2: Eel-Egg-Trick Boogaloo", description = "Those eels ate my brother.  My brother, {name}!  It's time someone showed 'em who's boss.\n\n<Humphrey removes several sticks of dynamite from his vest and shoves them through the egg's outer membrane.>\n\nThe great-eels to the south are too tough to fight one-on-one, but with this egg, we should be able to even the odds.  Place it near one of those creatures, then... kablooie!\n\nIf the bomb doesn't kill the eel outright, it should be near enough to death for you to finish it off.", sourceObjective = "Use the Eel-splosive Device near a Devious Great-Eel in Underlight Canyon, then defeat the Weakened Great-Eel.", completion = "Oskar's alive?  Wait... what did ya say?  Ya let him FLOAT AWAY AGAIN?!\n\nWell... ya held up your end of the bargain, and I appreciate everything ya've done, {name}.\n\nHere... take this.  I've only been hanging onto it as ballast, but it doesn't seem to be doing much good.", sourceObjectiveStatus = "unverified-source-field" }
quests[26022] = { id = 26022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Blood", description = "Be prepared, {name}. You will cast the first blood upon this land for us.\n\nThe Syndicate, as they call themselves, are cowardly humans who betray even their own kind. Their isolation will make them easy prey.\n\nTravel north, slay any Syndicate members you find, and claim Northfold Manor in the name of the Forsaken. Bring me the Bloodstone Amulets they wear as proof of your conquest.", sourceObjective = "Collect 10 Bloodstone Amulets from members of the Syndicate.", progress = "I won't be swayed by empty claims. Have you proof of your loyalty?", completion = "This is but a prelude to the slaughter we will visit upon these lands. All will know our name.\n\nYou have done well, {name}. Victory for Sylvanas!", sourceObjectiveStatus = "unverified-source-field" }
quests[26023] = { id = 26023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Trollbane", description = "Let me tell you a story.\n\nOnce, there was a foolish troll named Zengu. He was tasked to find the sword Trol'kalar, the legendary blade of the human Trollbane line. He succeeded, and thinking his task done, went to leave Arathi by himself. There he was cut down by the humans, and the sword simply reclaimed.\n\nWe will not be so foolish. Our apothecaries have given us the perfect guide to reobtain Trol'kalar: the prince who once held it.\n\nHe stands ready to guide you, {name}. Speak with him.", sourceObjective = "Speak with Galen Trollbane.", completion = "Yes... I was once Prince of the fallen kingdom of Stromgarde. I was cut down by the one seeking Trol'kalar.\n\nI rue my foolish life now. I serve...only Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26024] = { id = 26024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted! Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", sourceObjective = "Bring Marez's head to Captain Nials at Refuge Pointe.", progress = "Greetings, {class}.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, {name}.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26025] = { id = 26025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor Orc", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of her energy.\n\nFind the warlock and kill her. Bring me whatever magical object you find on her person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", sourceObjective = "Retrieve Marez Cowl's Befouled Bloodstone Orb.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, {name}. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26026] = { id = 26026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of a Better Tomorrow", description = "Mr. D is sick, <mister/miss>. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. D alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. D's stuff back so he can teach those baddies in the Alliance a lesson?", sourceObjective = "Recover the BD-816 War Apparatus, Mechanized Fire, Mechanized Ice and Mechanized Air.", progress = "Mr. D is so sad. We need to make him happy!", completion = "<Clarissa claps excitedly.>\n\nMr. D you're gonna be ok! Hooray!\n\n<Clarissa expertly places all of the parts you collected into Large Daddy.>\n\nOh, Mr. D! I knew it!", sourceObjectiveStatus = "unverified-source-field" }
quests[26027] = { id = 26027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms", description = "Our next strike against the ogres will bring you further east to Stromgarde. The living consider these gutted ruins worth clinging to. Their sentimentality is disgusting!\n\nAll that Stromgarde holds for us is a foul den of more ogres, waiting to be struck down. Travel there and slay their shamans and lords, and ensure what passes for leadership among the ogres is snuffed out.", sourceObjective = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords in Stromgarde.", completion = "Cleared out properly? Good. I doubt we'll even bother to lurk in Stromgarde. That ramshackle hole needs to be razed into dust.\n\nThe land would make a decent spot for a new Undercity in its place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26028] = { id = 26028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. D's Wild Ride", description = "Now Mr. D just needs an angel to help him navigate. Will you be that angel, <mister/miss>? With you helping we can go out into the crag and kill bunches and bunches of Alliance! Waddya say? Come on, <mister/miss>! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Alliance Mr. Krom'gar will buy us all ice cream!", sourceObjective = "Kill 20 Gnome Engineers and 5 Gnome Pounders.", completion = "<Overlord Krom'gar coughs.>\n\nI am - perhaps for the first time in my life - at a loss for words.\n\nI am really not sure where Clarissa even came from...", sourceObjectiveStatus = "unverified-source-field" }
quests[26029] = { id = 26029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Threat", description = "Or'Kalar leads the ogres here. He has evaded slaughter for years. His very presence is an affront to the Dark Lady; Mug'thol, traitor to the Forsaken, commands him from afar!\n\nWe do not suffer ogres or traitors on Forsaken land. Bring me this ogre's head and I will make sure it's burned properly this time.", sourceObjective = "Slay Or'Kalar and take his head.", progress = "Speak quickly.", completion = "This is the fate of all who would stand in our way.", sourceObjectiveStatus = "unverified-source-field" }
quests[26030] = { id = 26030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Strom", description = "In ancient times, Lord Ignaeus of Strom, named Trollbane, led the first human civilization of Arathor in war against the trolls. His blade was Trol'kalar--troll slayer, in their ancient tongue.\n\nI was one of the last of his line, sworn with guarding Trol'kalar...a duty in which I failed. But now, we will obtain it once more, for my new master.\n\nThe sword is bound by three sigils. The first is held by the Syndicate traitors that lurk the ruins of Stromgarde. Slay them, and return the sigil to me.", sourceObjective = "Collect the Sigil of Strom from Syndicate members in Stromgarde Keep.", progress = "Only the Syndicate agents in Stromgarde will have the sigil. Spilling blood outside the fortress's walls will be a waste of your time.", completion = "I hated the Syndicate in life as much as I do in death. To see the sigil again is a small comfort.\n\nBut we have much more work to do... for Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26031] = { id = 26031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Thoradin", description = "In life, I divided the sigil of Thoradin into five pieces to protect it, spreading it among my most loyal men. This too failed, but my successor will have done the same.\n\nThe defenders of Stromgarde hold the pieces of the sigil yet again. Slay them, and bring the shards to me; I will reassemble them.", sourceObjective = "Collect 5 Sigil Fragments from Stromgarde defenders in Stromgarde Keep.", progress = "All five pieces are needed to restore the sigil...", completion = "Thoradin was the founder of Arathor. Just as I join these fragments together, he joined the scattered tribes of humans into their first great nation.\n\nBut I'm sure you're not interested in such drivel. Forgive me. Old memories are often hard to bury.", sourceObjectiveStatus = "unverified-source-field" }
quests[26032] = { id = 26032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Arathor", description = "I entrusted the sigil of Arathor to Lieutenant Valorcall, leader of my cavalry. He barely escaped with his life when it was taken.\n\nIt is unlikely he will do so again. Valorcall patrols the road between Stromgarde Keep and Refuge Point. Find him, and take the sigil from him once more.", sourceObjective = "Collect the Sigil of Arathor from Lieutenant Valorcall.", progress = "Have you the sigil?", completion = "Valorcall was loyal to me in life. His death will not be something I bear lightly.\n\nBut bear it I must. I am Forsaken. My old existence means nothing.\n\nThe sigils are ours; Trol'kalar awaits.", sourceObjectiveStatus = "unverified-source-field" }
quests[26033] = { id = 26033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "The last sigil is mine...and with it, the four combine to the Sigil of Trollbane, key to the tomb. We are ready.\n\nTrol'kalar lies sealed with its master's remains, within Trollbane's tomb in the catacombs of Stromgarde. It will be defended heavily...but my presence before you is proof enough that the defenders can be overcome.\n\nEnter the tomb, retrieve Trol'kalar, and bring it here.", sourceObjective = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde Keep.", progress = "Have you Trol'kalar?", completion = "Trol'kalar, my father's blade... it seems like it's been an eternity since I saw it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Destroyer", description = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.\n\nZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.\n\nSlay him, {name}, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", sourceObjective = "Defeat Halion and repel the invasion of the Ruby Sanctum.", completion = "<Krasus listens intently as you relate your battle with Halion, and then his eyes go wide at the mention of Deathwing.>\n\nWe owe you a debt of gratitude, mortal, for driving the invaders from the Sanctum. But this news of the Destroyer is troubling beyond words. I have much to discuss with the other members of the Accord.\n\nTake these as a token of my thanks, as you gird yourselves for the coming storm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26035] = { id = 26035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worth Its Weight in Gold", description = "Archmage Malin sent me here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need Witherbark tusks and Witherbark medicine pouches.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", sourceObjective = "Collect 10 Witherbark Tusks and 4 Witherbark Medicine Pouches from Witherbark Trolls.", progress = "Have you had any luck so far?", completion = "Not bad. Since it's clear you've got your head on straight, I was hoping you could help us with a more pressing job.", sourceObjectiveStatus = "unverified-source-field" }
quests[26036] = { id = 26036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wand over Fist", description = "Hey, {name}. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", sourceObjective = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", progress = "Our goal is the wand, {name}. Focus on that for now.", completion = "Brilliant, {name}. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26037] = { id = 26037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to ward you against the tower's defenses. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant it.", sourceObjective = "Find an Azure Agate and bring it to Apprentice Kryten at Stromgarde Keep.", progress = "{name}, hello again. Have you found an azure agate yet?", completion = "You amaze me, {name}. Well done again.\n\nGive me a moment to cast the proper spell an' you'll be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[26038] = { id = 26038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on the Tower", description = "Here's what you're looking for: Trelane's phylactery, Trelane's orb, and Trelane's ember agate.\n\nAll three should be in chests within the tower.  You shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nYou'll need to have your weapons at the ready. Those ogres find out you're there and stealing from them, and they'll be sure to put the hurt on you.\n\nBe careful, and good luck.", sourceObjective = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, {name}. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been.", sourceObjectiveStatus = "unverified-source-field" }
quests[26039] = { id = 26039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, {name}, aid me!", sourceObjective = "Gather 12 Motes of Myzrael from Drywhisker Kobolds.", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free...", sourceObjectiveStatus = "unverified-source-field" }
quests[26040] = { id = 26040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", sourceObjective = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, {race}?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can wean off of it and avoid the side-effect.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26041] = { id = 26041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", sourceObjective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble {class}, {name}.  My rescuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[26042] = { id = 26042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n{name}, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", sourceObjective = "Obtain the Rod of Order from Fozruk.", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you...", sourceObjectiveStatus = "unverified-source-field" }
quests[26043] = { id = 26043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BEWARE OF CRAGJAW!", description = "By order of Overlord Krom'gar, Cragpool Lake is OFF LIMITS!\n\nThe ferocious beast known as Cragjaw has made the lake a death trap. Should you dispatch of Cragjaw, take his huge tooth as a trophy and return it to Spy-Mistress Anara for a reward.", sourceObjective = "Kill Cragjaw and take Cragjaw's Huge Tooth.", progress = "What is it that you require?", completion = "A testament to the might of the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26044] = { id = 26044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are the Parts?", description = "I've been waiting on parts for these guns for days! I sent one of my best blastgineers and two dozen miners into the Deep Reaches five days ago for the parts. After not hearing from anybody for three days I began to get a little worried. The Overlord sent two of his best orcs in to see what was going on. We've received no reports since then...\n\nHead into the Deep Reaches, directly below this fortress, and find out what's going on! I need parts!", sourceObjective = "Speak to Sergeant Dontrag inside the Deep Reaches in Stonetalon Mountains.", completion = "Um... Well you see, it's quite simple... THIS CAVE IS SWARMING WITH SOULLESS KILLING MACHINES!", sourceObjectiveStatus = "unverified-source-field" }
quests[26045] = { id = 26045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Got Your Parts Right Here...", description = "Here's the dilemma: I could do one of two things, get killed down here like everyone else or get killed up at Krom'gar Fortress when Krom'gar realizes we've lost the mine. I'm choosing the third option, do nothing. So far, so good.\n\nYou need parts? Plenty from the left over junk scattered about in this mine. You just gotta go get 'em.\n\nGood luck! Maybe if you get those parts we might be able to show our faces at Krom'gar Fortress.", sourceObjective = "Collect 10 Spare Parts.", progress = "How's that part hunt going?", completion = "I'll be damned! You managed to get the parts and not die. How are you only a sergeant?", sourceObjectiveStatus = "unverified-source-field" }
quests[26046] = { id = 26046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Rock and a Hard Place", description = "Dontrag can explain it better than me. Basically, we're stuck between a rock and a hard place. Can't do anything down here due to all of the things that can kill us and can't go back to the base due to all of the things that can kill us - you know?\n\nPerhaps if we worked together we might be able to get this mess sorted out. How about you get started by clearing out some of these elementals that have apparently killed everything in the mine, ok?", sourceObjective = "Kill 12 Raging Earth Elementals.", completion = "Get the parts, kill the elementals and rescue the peons... We get all of that done and we're as good as promoted!", sourceObjectiveStatus = "unverified-source-field" }
quests[26047] = { id = 26047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And That's Why They Call Them Peons...", description = "These two are USELESS! When they first arrived I thought we were saved. Not so! Instead, Dontrag and Utvoch took one look at the mine and concocted some idiotic plan that involved standing here until... until we all died, I guess. \n\nYou don't look nearly as useless. How about you lend a hand, friend? I've got dozens of peons, scared out of their gourds, hiding in the Deep Reaches. Find them and get them out!", sourceObjective = "Rescue 10 Frightened Peons.", progress = "Did you find my peons?", completion = "I knew it! You are a hero! If I have anything to do with it, you'll be promoted to legionnaire!", sourceObjectiveStatus = "unverified-source-field" }
quests[26048] = { id = 26048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts Up In Here!", description = "Whew, that was tough. I didn't think we'd make it, {name}. We better get these parts back to Chief Blastgineer Bombgutz. I think I hear the gnome flying machines buzzing outside. We haven't got a minute to lose!", sourceObjective = "Deliver the Crate of Spare Parts to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", progress = "Get my parts?", completion = "Just in time! The flying machines are starting to mass. Attack is imminent!", sourceObjectiveStatus = "unverified-source-field" }
quests[26049] = { id = 26049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Unleashed", description = "Myzrael's no innocent princess. She's a terribly dangerous force, and the giants had every reason to chain her down there. I'm afraid you've been had.\n\nAccording to Gerrig, you have to summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards.\n\nHere's the scroll you'll need. Be careful with it; I risked a few teeth to get it. Good luck, {name}.", sourceObjective = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", sourceObjectiveStatus = "unverified-source-field" }
quests[26050] = { id = 26050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goggle Boggle", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", sourceObjective = "Escort Professor Phizzlethorpe to the cave and back.", completion = "The goggles work perfectly now! Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26051] = { id = 26051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, {name}, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", sourceObjective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, {name}! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!", sourceObjectiveStatus = "unverified-source-field" }
quests[26052] = { id = 26052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Shakes", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, {name}, take these to O'Breen.", sourceObjective = "Take the Elven Gems to Captain O'Breen at Faldir's Cove in Arathi Highlands.", progress = "Ahoy, {class}.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!", sourceObjectiveStatus = "unverified-source-field" }
quests[26053] = { id = 26053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Highlands", description = "No threat here will go overlooked. If we are to secure these lands under the Dark Lady's rule, we will tear from them everything living, inch by inch, piece by piece.\n\nTo the northeast, not a stone's throw away from this camp is an ogre mound. The Boulderfist ogres that dwell in it must be eradicated, {class}.\n\nThey are in the way. Show no mercy or hesitation.", sourceObjective = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers.", completion = "Excellent. The march of the Forsaken continues.", sourceObjectiveStatus = "unverified-source-field" }
quests[26054] = { id = 26054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water They Up To?", description = "Sandfury trolls working with the Twilight's Hammer?!\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Kai'ju Gahz'rilla and inform General Marcus Jonathan in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[26055] = { id = 26055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", sourceObjective = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", progress = "Bah, maybe I should go kill those naga scum myself.  It's obvious you're not goin' to do it.\n\nMaybe I can find some knitting needles so you can keep yourself busy.", completion = "Nice work out there, {name}.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace.", sourceObjectiveStatus = "unverified-source-field" }
quests[26056] = { id = 26056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", sourceObjective = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26057] = { id = 26057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", sourceObjective = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26058] = { id = 26058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Krom'gar Fortress", description = "There's no time left. Here they come! Take control of a heavy gun and shoot the gnomes out of the sky! If that bomb takes too many hits it will blow, taking us all with it!\n\nDefend the base, {name}! You're our only hope!\n\nIf we somehow make it out of this in one piece, report to Overlord Krom'gar.", sourceObjective = "Destroy 15 Gnomish Flying Machines or Bombers and 25 Gnome Wing Commanders.", progress = "Our enemies surround us!", completion = "I have never seen such an act of bravery. You saved the base, sergeant - or should I say legionnaire! Lok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26059] = { id = 26059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes and Ears: Malaka'jin", description = "Honor's Stand has been lost. The Horde's grip on the Barrens shattered along with the land itself. I now receive reports that we are at risk of losing Malaka'jin to a concerted attack by the Alliance and the Grimtotem. If Malaka'jin falls, half of Stonetalon falls with it!\n\nYou have proven yourself a capable soldier of the Horde. Will you be my eyes and ears at Malaka'jin? Witch Doctor Jin'Zil awaits your arrival.\n\nMalaka'jin is located far to the south.", sourceObjective = "Report to Witch Doctor Jin'Zil at Malaka'jin in Stonetalon Mountains.", completion = "I see that Krom'gar has sent his best!\n\nGood, we have much work to do. The filth that is the Alliance have entered into a treaty with the Grimtotem. Now we fend off attacks from both forces.\n\nWe are spread thin across the Greatwood Vale and will soon fall beneath the concerted effort of our enemies. There is only one hope: VOODOO!", sourceObjectiveStatus = "unverified-source-field" }
quests[26060] = { id = 26060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Stormer Heart", description = "With voodoo, our troops might have a chance at beating back the Grimtotem assault. With that said, I need several ingredients if I am to invoke black magic.\n\nThe first ingredient on my list is a heart from a cliff stormer. The beasts have nearly been hunted to extinction, but a few still exist around these parts. Find one and recover its beating heart!", sourceObjective = "Obtain a Cliff Stormer Heart.", progress = "I need the cliff stormer heart.", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26061] = { id = 26061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Ram Horns", description = "If I am to invoke voodoo, I will need several special reagents. Bring me horns from the Stonetalon rams of the region, {name}! Without the horns we are done for!", sourceObjective = "Obtain 6 Stonetalon Ram Horns.", progress = "I need the Stonetalon ram horns!", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26062] = { id = 26062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Resonite Crystal", description = "The final ingredient for the voodoo ritual is a special type of crystal called resonite. It can only be found in the Boulderslide caverns, west of here. Beware the kobolds! They guard the resonite with their lives!", sourceObjective = "Obtain 8 Resonite Crystals.", progress = "I need the resonite crystals!", completion = "Finally! Now I will create the charm that will hold the voodoo enchantment!", sourceObjectiveStatus = "unverified-source-field" }
quests[26063] = { id = 26063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen and Her Court", description = "<Darn grunts.>\n\nHrmph.\n\nThings falling apart. Darn not happy. Now Darn's mate killed by spiders at Webwinder Hollow. Darn demands vengeance!\n\nHelp Darn? Kill Queen Silith and her little spiderlings? For Darn? For Darn's mate!\n\nWebwinder Hollow is northwest of here, up the path. Go!", sourceObjective = "Kill Queen Silith and any 10 spiders in Webwinder Hollow.", completion = "Darn still not very happy, but Darn will reward you for what you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[26064] = { id = 26064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight On Their Stomachs", description = "The troops are hungry, {name}. With our supply lines cut off, we're steadily running out of food. I can cook the soldiers a feast if you can get me some ingredients.\n\nHead into the woods west of here and look for Kalimdor eagle nests. Steal the eggs from the nests and bring them back to me.", sourceObjective = "Collect 8 Kalimdor Eagle Eggs.", progress = "I need eggs!", completion = "Thank you, {name}. These eggs should get us through the week.", sourceObjectiveStatus = "unverified-source-field" }
quests[26065] = { id = 26065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Wil'hai", description = "Those tentacle horrors rising from the depths have trapped that poor beast. Please, {name}, can you save it by destroying those things?\n\nWill you free Wil'hai?\n\nHere, take my totem and plant it near the tentacles. The cold it emanates will cause major shrinkage on those monsters and then you'll be able to destroy them.", sourceObjective = "Slay all of the Tentacle Horrors to free Wil'hai.", progress = "Wil'hai is still trapped.", completion = "Thank you, {name}.\n\nThese nightmarish creatures that rise from below give me pause. I fear that our efforts will be for nothing.", sourceObjectiveStatus = "unverified-source-field" }
quests[26066] = { id = 26066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements...", description = "It would appear as if we are running out of big, stupid orcs to send at the enemy. This is a problem. Thankfully, I may have a solution.\n\nTake this whip and head west to Boulderslide Cavern. Within the cave you will find a filthy nest of kobolds. Use my whip to subdue the beasts. Once subdued they will do whatever we ask them to do.\n\nReturn to me when you have amassed a sizable army of kobolds.", sourceObjective = "Use Subjugator Devo's Whip to Subdue 6 Boulderslide Kobolds.", progress = "Do not dilly-dally, {name}.", completion = "In times of crisis, a desperate act may be all that is needed to secure victory. Sending a swarm of kobolds at the enemy may be the edge that we need to win.", sourceObjectiveStatus = "unverified-source-field" }
quests[26067] = { id = 26067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zil's Blessing", description = "Ah, it is done! Now to test it out.\n\nTravel to the main point of conflict within Greatwood Vale and use my voodoo stick on the Krom'gar marauders battling the Grimtotem. My voodoo magic should renew their vigor and allow them to crush our enemies!\n\nGo now, {name}!", sourceObjective = "Use Jin'Zil's Voodoo Stick to infuse 12 Krom'gar Marauders with Voodoo.", progress = "Hurry, {name}!", completion = "Victory, at last! Though it stands to reason that without a stable supply line this victory will be short lived. Enjoy it while it lasts, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26068] = { id = 26068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Fury!", description = "We now command the kobold armies of Stonetalon! It almost sounds impressive. Almost.\n\n<Devo sighs.>\n\nThe Alliance base camp north of here is tightly guarded. It is nigh impregnable, save for the entry point by the Unearthed Grounds, northeast of here. Take this kobold war horn and head towards the Unearthed Grounds. Enter from the east, {name}! Once there, head west until you arrive at the location I have marked upon your map. Use the horn there to unleash kobold fury upon the Alliance!", sourceObjective = "Use the Kobold War Horn near the Horde Banner at the Unearthed Grounds to unleash the Kobold Army!", progress = "On my mark, unleash kobold hell!", completion = "<Devo laughs.>\n\nFascinating tale, friend. It would seem that our newfound kobold allies might be somewhat useful after all!", sourceObjectiveStatus = "unverified-source-field" }
quests[26069] = { id = 26069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nura Pathfinder", description = "Southern Barrens is under attack by the Alliance. The tauren have sent out a call for help that we simply cannot ignore. All able bodied soldiers of the Horde should assist.\n\nIf you wish to help, take the path to the High Road, located in the village. Seek out Nura Pathfinder.", sourceObjective = "Report to Nura Pathfinder on the High Road in Southern Barrens.", completion = "The situation is grim, {race}. We need all of the help that we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[26070] = { id = 26070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Defiled", description = "Our Earthen Ring friends here are wondering if we can lend them a hand. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nCan you take care of that for me?", sourceObjective = "Slay any 8 Crushing Eels, Deep Remoras, or Chasm Stalkers.", completion = "Good enough for me.\n\nDon't get too complacent, {name}. The hard part's about to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[26071] = { id = 26071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Defiled", description = "These Earthen Ring want us to do their killing for them. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nSwim down there and take care of it.", sourceObjective = "Slay any 8 Crushing Eels, Deep Remoras, or Chasm Stalkers.", completion = "Well done.\n\nDon't get too full of yourself, {name}. The hard part's about to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[26072] = { id = 26072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Totem", description = "You must take my totem down into the Scalding Chasm. Use it to capture the energies of the faceless as they die. The totem will keep them from returning from whence they came.\n\nWhen the totem is full, bring it back to me and we will use it to lure their leader up from deep down below.", sourceObjective = "Slay 5 Faceless Defilers while they are within range of the Confinement Totem.", completion = "Yes, {race}, can you feel them seething with a desire to break free and destroy us?\n\nThis is good! They will be the perfect lure for their leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[26073] = { id = 26073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Quiet on the Southern Front", description = "Return now to Overlord Krom'gar, {name}. Inform him of our status and of what you have done to ensure that Malaka'jin does not fall.\n\nWe thank you for all that you have done. Perhaps some day soon you will have your own region to command.", sourceObjective = "Report to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", completion = "Lok'tar ogar! You are the embodiment of what it means to be a Horde soldier, {name}. If only we had more like you, this war would be over and Kalimdor would belong to the Horde - UNCONTESTED!\n\nRise now as a champion of Krom'gar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26074] = { id = 26074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning of the End", description = "Champion, we have acquired a new target. Our scouts in Battlescar Valley report that the night elves are preparing their own weapon of mass destruction and hiding it within an ancient tree. They will never be given the chance to use their weapon against us.\n\nYou are to escort the bomb to the Sludgewerks for refueling and then to Cliffwalker Post, from which we will detonate the bomb and kill all of our enemies.\n\nGo now, {name}. Report to Jibbly Rakit when you arrive at the Sludgewerks.", sourceObjective = "Take the Krom'gar Hot Air Balloon to the Sludgewerks in Stonetalon Mountains.", completion = "Krom'gar has sent his champion! Well you haven't a thing to worry about, Champion. We'll get the balloon all fueled up in no time. How about you lend a hand around here while you wait?", sourceObjectiveStatus = "unverified-source-field" }
quests[26075] = { id = 26075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Turd Problem", description = "We have a little problem...\n\n<Jibbly points to the large turds covering the base.>\n\nWe built the Sludgewerks near a wyvern habitat. Now our initial blueprints for the Sludgewerks were drawn up so as not to disturb the wyvern habitat as the beasts are apparently sacred to tauren and orcs. Do you know what's sacred to me? Not getting pooped on, that's what!\n\nBetween you, me and the wall, the wyvern must die!", sourceObjective = "Kill any 6 Pridewing Wyvern.", progress = "Please help. The guards are getting a little uppity.", completion = "I sure hope you didn't miss any. I don't think I can take much more of this!", sourceObjectiveStatus = "unverified-source-field" }
quests[26076] = { id = 26076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Infestation", description = "We've got another problem, {name}. Alliance spies are all over the place! You haven't seen any? That's because they're invisible! Cloaked! I have a solution, but I need muscle like you to go out there and follow through with my plan.\n\nUse this gas bomb on the cloaked spies and it will reveal them. Once revealed, send them back to their maker.\n\nYou'll know a cloaked spy by the effect they leave in the air. Look closely!", sourceObjective = "Kill 8 Alliance Spies. Use Jibbly's Gas Bomb to uncloak the spies!", progress = "Have you dealt with the spy infestation?", completion = "And they called me crazy. I knew this place was crawling with spies. Poop too.", sourceObjectiveStatus = "unverified-source-field" }
quests[26077] = { id = 26077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Delivery", description = "Overlord Krom'gar sends word from the base. You are to get back on the Krom'gar hot air balloon and take it to Cliffwalker Post. From there, the plan is to unleash the payload on the Alliance at Battlescar Valley.\n\nYou better get going, {name}. It's not wise to keep Krom'gar waiting.\n\nSpeak to General Grebo when you arrive at your destination. He'll be able to brief you on the next course of action.", sourceObjective = "Take the Krom'gar Hot Air Balloon to Cliffwalker Post in Stonetalon Mountains.", progress = "Attention, soldier!", completion = "Chieftain Cliffwalker and his tauren seek to commit treason against the Horde! They claim that the ancient tree at the heart of Battlescar Valley is merely a school for druids. They are blind to the fact that desperate measures are taken during war time. My scouts have assured me that the night elves hide a weapon of great power within that tree. We're going to end this now!", sourceObjectiveStatus = "unverified-source-field" }
quests[26078] = { id = 26078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguish the Fires", description = "The Dark Iron attack took us by surprise. Their saboteurs managed to damage most of our aircraft, steam tanks, and supplies. We were only able to get a few of our bombers airborne.\n\nEvery technician, recruit, and guard I can spare is  scrambling to get the others repaired and flight-ready. Our infantry can only hold out for so long. Take this equipment and help extinguish the burning bombers.", sourceObjective = "Using the Firefighting Equipment, extinguish 6 fires at the Ironforge Airfield.", progress = "We need to hurry and get those bombers airborne!", completion = "Well done! My men are working hard on getting our flying machines and steam tanks back into the fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[26079] = { id = 26079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted! Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", sourceObjective = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, {name}.  I am happy to pay it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26080] = { id = 26080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Favor", description = "{name}, I'm gonna need ya to bring this back to Captain Glovaal.  With my condition, it'll take me a week to get back to Darkbreak Cove, and we don't have any time to waste.", sourceObjective = "Deliver Digsong's Fish and Tips to Captain Glovaal at Darkbreak Cove.", progress = "Have you found Oskar and Humphrey?", completion = "I see.  Yes, I am rememberink now... Humphrey and Oskar vere not the strongest svimmers.\n\nThe reconnaissance is helpful, and the extra fish look very tasty.  If you are seeink Mister Digsong before he returns, please send him my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26081] = { id = 26081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alina's Reward", description = "The tale of Trol'kalar ends here, then. It will be a weapon to bring death to the living, in the name of the Dark Lady.\n\nLeave me now, {name}. My job is once again to guard the blade. Tell Alina of your victory, I'm sure she will have a reward for you.", sourceObjective = "Speak to Dark Ranger Alina.", completion = "The news of your victory satisfies me, {class}... a rare sensation. The Dark Lady herself has mused that our conquest of Lordaeron may be the only way the Forsaken can find true satisfaction, and pehaps even relief.\n\nBut it matters not. Our victory is inevitable. For your loyal service to the Forsaken, I award you in the name of Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26082] = { id = 26082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Battlescar!", description = "I will allow this old fool time to plead his case. He has assured me that he will bring back proof that the night elves do not harbor a weapon of mass destruction. We shall see.\n\nWhile we await this proof, you will assist our army in the valley. We have prepared a large number of siege tanks for this purpose. Our demolishers are poised for attack.\n\nTake the elevator down to the base of the outpost and take control of a Krom'gar demolisher. Use it to lay waste to our enemies in Battlescar Valley.", sourceObjective = "Use the Krom'gar Demolisher to destroy 5 Darnassian Glaive Throwers and any 20 Alliance soldiers in Battlescar Valley.", progress = "Slay them all!", completion = "You possess quite a talent for destruction, {name}. Whatever Alliance remain after your rampage across Battlescar Valley will be dealt with by the bomb.", sourceObjectiveStatus = "unverified-source-field" }
quests[26083] = { id = 26083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hello Lolo", description = "Goutgut get sent scouting. Look at many things. Big adventure!\n\nGoutgut found secret pirate ship. Pirates all scared, run away. But ogre Lolo not run. Lolo make friend with Goutgut!\n\nGoutgut have to leave, but miss Lolo. You go say hello to Lolo for Goutgut.", sourceObjective = "Find Lolo the Lookout at Faldir's Cove.", completion = "You friends with Goutgut! Him weird ogre. Smell funny.", sourceObjectiveStatus = "unverified-source-field" }
quests[26084] = { id = 26084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "You have served us well here, {name}. Now that we've made our mark, the next phase of our conquest will occur over months rather than minutes.\n\nThere is much work yet to be done, and I will spare you the tedium of waiting for our fortifications to trickle in. Travel to the east, to Hammerfall. The orcs there will no doubt have use of your aid.", sourceObjective = "Report to Gor'mul at Hammerfall in Arathi Highlands.", completion = "Throm'ka, {class}. If your deeds for the undead are as great as you claim, I am honored to help you serve the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26085] = { id = 26085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Defenders", description = "While our engineers work on getting the bombers ready to fly again, our guards and mountaineers continue to fight the invaders.\n\nThey've been out there since the incursion began, without so much as a chance to catch some sleep or have a meal. Ironforge's defenders are among the best on Azeroth, but even they have limits.\n\nTake these banners and plant them in banks of loose snow. Remind the men what they are fighting for and help keep their morale high.", sourceObjective = "Plant 8 Ironforge Banners in mounds of Loose Snow throughout the Ironforge Airfield.", completion = "The men are finding hidden reserves of strength and courage to deal with the Dark Iron onslaught. The airfield will not fall on our watch!", sourceObjectiveStatus = "unverified-source-field" }
quests[26086] = { id = 26086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orako", description = "<Captain Verne looks down at his watch.>\n\nWhere is that hunter?  I sent Orako to Underlight Canyon to prepare a recon report a week ago!  Sure, he's a handful, and I didn't mind getting him out of my hair, but I need his report.\n\nSay, what's your name?  {name}?  Would you be willing to go track him down?  It seems strange to send a {class} to find a hunter, but I'm running out of options.", sourceObjective = "Report to Orako at Underlight Canyon in Vashj'ir.", completion = "Gah!  These fish are impossible to hit!\n\n<Orako looks at you.>\n\nMy wolf got eaten by a fish, and I'm not going back until I find her.", sourceObjectiveStatus = "unverified-source-field" }
quests[26087] = { id = 26087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Glow-Juice\"", description = "Shooting fish in a barrel is easy.  Shooting fish in an ocean is a little harder.\n\nHave you seen the murlocs down in the canyon, {class}?  They don't shoot at all!  They have little balls full of glow-juice on their heads that make the fish come to THEM.  Hey, we should try that!\n\nGo south, and kill the crabs and groupers in the canyon.  They have lots of glow-juice in their skin.  I've seen it!", sourceObjective = "Obtain 6 gobs of Glow-Juice from Pyreshell Scuttlers and Luxscale Groupers in Underlight Canyon.", progress = "We need lots and lots of glow-juice.", completion = "Hey, look at how glowy it is!\n\n<Orako looks wistfully off into the distance.>\n\nMy wolf loved things that were glowy...", sourceObjectiveStatus = "unverified-source-field" }
quests[26088] = { id = 26088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here Fishie Fishie", description = "<Orako rolls the glow-juice into a ball, then attaches it to a device that he's clearly been working on for a long time.>\n\nHere, I got you this hat.  It has a light on it, and it will make fish follow you.  Just like the murlocs!\n\nThe murlocs like to hunt in the kelp and coral along the sides of the canyon.  If you put on this hat and swim in that kelp, you might catch some fish like they do.", sourceObjective = "Put on the Fish Hat, then swim through the coral in Underlight Canyon to attract 30 Underlight Nibblers.", progress = "How many did you catch?", completion = "Hmm... you got a lot of fish, but none of these are the ones that ate my wolf.  I think it was probably a bigger fish.", sourceObjectiveStatus = "unverified-source-field" }
quests[26089] = { id = 26089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fishman Die", description = "A fish ate my wolf, and murlocs look like fish.  I'm going to make those murlocs pay!\n\nHead back down to the canyon and kill the fishmen!  My wolf will be avenged!", sourceObjective = "Kill 4 Coldlight Hunters and 4 Coldlight Oracles.", completion = "I know, murlocs aren't fish.  I thought that killing them would make me feel better, but I still feel sad about my wolf.\n\n<Orako sighs.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26090] = { id = 26090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Brought You This Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Orako might be interested in something like this.>", sourceObjective = "Deliver the Enormous Eel Egg to Orako at Underlight Canyon in Vashj'ir.", progress = "<Blam!>\n\nYou brought me something?", completion = "That is a big egg.\n\n<Orako sniffs it.>\n\nIt is big, and it smells like fish.  Maybe the big fish that made this egg is the big fish that ate my wolf!", sourceObjectiveStatus = "unverified-source-field" }
quests[26091] = { id = 26091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here Fishie Fishie 2: Eel-Egg-Trick Boogaloo", description = "<Orako removes an explosive trap from his sack and shoves it through the egg's outer membrane.>\n\nThis will make the egg explode.  Place the egg down next to one of those giant eels, and wait for them to come close.  When the egg explodes, the big fish will be almost dead, and you can finish killing it.\n\nSave my wolf!  With this egg, you can do it.", sourceObjective = "Use the Eel-splosive Device near a Devious Great-eel in Underlight Canyon, then defeat the Weakened Great-Eel.", progress = "Save my wolf, {name}.", completion = "<Orako is busy playing with Wolf.>\n\nOh, thank you, {name}!  I knew Wolf was alive!\n\nHere, take one of these.  I don't need them anymore.", sourceObjectiveStatus = "unverified-source-field" }
quests[26092] = { id = 26092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orako's Report", description = "<You remind Orako that he was supposed to send a report back to Captain Verne.>\n\nRight, a report.  All that I've seen here is fish.  Lots and lots of fish.\n\n<Orako looks over at the sack of fish that you brought for him.>\n\nBring this back to the captain.  This is my report.", sourceObjective = "Deliver Orako's Report to Captain \"Jewels\" Verne in Tenebrous Cavern.", progress = "Where was he?  What happened?", completion = "This is his report?!  That idiot...\n\nI suppose we can use the food.  Thanks, {name}.  You've done as well as can be expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[26093] = { id = 26093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nThough Southshore has fallen, we must not let any further ground be yielded to our enemies.\n\nGo to the Syndicate base in Northfold Manor and slay them. We must reclaim the land for ourselves before the Horde has a chance to creep further.", sourceObjective = "Kill 10 Syndicate members at Northfold Manor.", completion = "Very good, {name}.  The last thing we need with the undead looming is a gang of common thieves distracting us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26094] = { id = 26094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "My chief engineer tells me that he's managed to get one of the bombers repaired and airworthy. Take these bombs with you, and look for the repaired bomber at the start of the runway.\n\nOnce you're airborne, use the bombs to do as much damage to the attacking Dark Iron dwarves as you can. I've heard rumors that they're preparing to deploy a new kind of war golem. Keep your eyes peeled for those golems and make them your highest priority targets.", sourceObjective = "Board the Repaired Bomber and use the Iron Hammer Bomb to kill 30 Dark Iron attackers. You may kill any of the Dark Iron dwarves or their allies at the Ironforge Airfield.", progress = "At last, we finally have a chance to hurt the Dark Iron attackers.", completion = "The momentum is starting to shift, {name}, largely due to your efforts. Now, it is time to strike at the Dark Iron leadership.", sourceObjectiveStatus = "unverified-source-field" }
quests[26095] = { id = 26095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", sourceObjective = "Collect 7 Stromgarde Badges from Syndicate enemies in Stromgarde Keep.", progress = "Have you retrieved any Stromgarde Badges, {name}?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, {name}.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.", sourceObjectiveStatus = "unverified-source-field" }
quests[26096] = { id = 26096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalding Shrooms", description = "We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it.\n\nDown below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.", sourceObjective = "Collect 5 Scalding Shrooms.", progress = "I heard that you had an unpleasant encounter with putting one of the demons on your head. I can assure you that they are now all quite dead.", completion = "I will use the mushrooms as a reagent to treat the corpses. We will have one ready for you soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26097] = { id = 26097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Lies", description = "At the heart of Battlescar Valley stands an ancient tree - a tree that has withstood the force of ages and has served as a place of peace and learning for generations. My kin have studied druidism at the grove, alongside the night elves, for as long as I can recall. Now I am to believe that the tree holds within it an Alliance weapon of mass destruction?\n\nKrom'gar is wrong and I will prove it!\n\nI have sent my son, Orthus, to Thal'darah Grove in search of this weapon. Go there now and meet him.", sourceObjective = "Find Orthus at Thal'darah Grove in Stonetalon Mountains.", completion = "Orthus is dead. He is clutching something in his hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26098] = { id = 26098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal at the Grove", description = "Druid corpses litter the room. Something seems amiss, as you see no signs of a struggle.  Bloody drag marks lead in from the doorway.\n\nYou pry Orthus' death grip open to find something disturbing in his hand: a Krom'gar General's insignia.\n\nTake the Krom'gar General's insignia back to High Chieftain Cliffwalker.", sourceObjective = "Take the Krom'gar General's Insignia back to High Chieftain Cliffwalker at Cliffwalker Post in Stonetalon Mountains.", progress = "He... My child is dead?", completion = "<High Chieftain Cliffwalker takes the insignia from you.>\n\n<High Chieftain Cliffwalker cries out in anger.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26099] = { id = 26099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This Justice?", description = "He was a good boy, {name}. Young, loving. He would have never killed any of the young druids. They were his friends! No... Not Orthus.\n\nThe General must be called to answer for this crime. I will have justice!", sourceObjective = "Defend yourself.", progress = "This is justice.", completion = "You saw with your own eyes, {name}. General Grebo attacked us!\n\n\n\nNow what will we do? Surely the Warchief will have us all executed for treason.", sourceObjectiveStatus = "unverified-source-field" }
quests[26100] = { id = 26100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The General is Dead", description = "Perhaps if you spoke to Overlord Krom'gar, {name}. Maybe he would listen to what you had to say? You are a Champion in his army, after all. You saw everything. Please help us, {name}. We simply wish to be left alone - in peace.\n\nTalk to Overlord Krom'gar and try to help him see that we did not mean for any of this to happen.", sourceObjective = "Speak to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", completion = "WHAT? My General has been killed by the tauren? This is treason! HIGH TREASON! They will pay for this grievous error.", sourceObjectiveStatus = "unverified-source-field" }
quests[26101] = { id = 26101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might Makes Right", description = "You have done well to report this crime. The perpetrators of this heinous act will be punished. There will be blood.\n\nI will need a new General now that Grebo is dead. You shall take his place.\n\nMeet me at Cliffwalker Post, General. Together we will end this nonsense.", sourceObjective = "Meet Overlord Krom'gar at Cliffwalker Post in Stonetalon Mountains.", completion = "The traitorous tauren will now stand by as we destroy his precious grove and burn his village to the ground!", sourceObjectiveStatus = "unverified-source-field" }
quests[26102] = { id = 26102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimaxe's Demise", description = "With you leading the way, we've finally broken the momentum of the Dark Iron attack. General Grimaxe, the Dark Iron leader, is attempting to rally his troops from the center of their lines on the frozen lake to the south.\n\nHe stands atop one of their new dark iron golems, shouting orders to his men. If he succeeds in rallying them, they may still be able to overpower us. You must prevent that, {name}. Destroy the golem guarding him, then kill General Grimaxe himself. He is the key to our victory.", sourceObjective = "Kill General Grimaxe at the Ironforge Airfield.", progress = "If we can defeat General Grimaxe, the Dark Iron forces won't be able to regroup.", completion = "We've done it! Without your help, Ironforge Airfield would surely be occupied by the enemy and the Dark Irons would have a clear road to Ironforge itself.\n\nThe Council of Three Hammers must be informed of what happened here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26103] = { id = 26103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bio-Fuel", description = "Submarine fuel is expensive!\n\nThe powers-that-be in Gnomeregan were generous enough to deliver several fuel barrels, but we're burning through it faster than expected.  That means we're going to need to improvise.\n\nIt's a well-known fact that sea creatures are full of all kinds of interesting chemicals... like oil.  Take this device up to Kothrun's End and stick it into the corpses of terrapins, remoras, and hammerhead sharks.  If we don't get more submarine fuel, their oil might be our only hope.", sourceObjective = "Use the Oil Extrusion Pump on the corpses of Seabrush Terrapins, Scourgut Remoras, and Spinescale Hammerheads in Kothrun's End to obtain 4 Terrapin Oil, 4 Remora Oil, and 4 Hammerhead Oil.", progress = "How did the device work, {name}?", completion = "<Engineer Hexascrub sticks a finger into each sample and sniffs it.>\n\nYes, I think this will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26105] = { id = 26105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim Korthun's End", description = "The Horde has spies in this area?  Darkbreak Cove is nearby, and inside lies the Pincer X2!  The Horde must not be allowed anywhere nearby!\n\nSomeone in Darkbreak Cove will want to hear of this... after you finish slaying some more of these dirty Horde spies.", sourceObjective = "Kill 7 Hellscream Seadogs in Korthun's End.", completion = "You did well, {name}.  We need to be especially wary of Horde attacks right now.  The Pincer X2 has plenty of firepower at sea, but in the back of this cave, she is exceptionally vulnerable.", sourceObjectiveStatus = "unverified-source-field" }
quests[26106] = { id = 26106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel-ology 101", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", sourceObjective = "Use the Fuel Sampling Station in Darkbreak Cove to create the perfect bio-fuel.", progress = "We haven't found the right combination yet, {name}.  Keep at it!  I'm sure you can figure it out!", completion = "Have you considered a career in science, {name}?  If you ever get tired of this {class} nonsense, come see me!  I could use an assistant with your devotion to experimentation and the scientific method.", sourceObjectiveStatus = "unverified-source-field" }
quests[26107] = { id = 26107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "Our race's gift of shamanism stirred me from a years-long lethargy. Now I provide for all here, crafting the same boons that gave me newfound strength.\n\nThe Highland raptors are cunning and fierce beasts. Their spirits can grant our warriors great strength. Bring me raptor eyes, so I may make the amulets as Tor'gan taught me.", sourceObjective = "Collect 10 Highland Raptor Eyes from Highland Striders or Highland Thrashers.", progress = "The fierceness in the eyes of the raptors will be matched by those of our warriors.", completion = "The lethargy that overcame me even after the camps fell was so strong, I refused this gift when it was first given to me.\n\nNow, I am proud to do my part in the name of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26108] = { id = 26108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guile of the Raptor", description = "The highland fleshstalkers to the south are even fiercer than the others of their kind. They possess not just strength, but true cunning.\n\nWhen I was trapped by lethargy, even the amulets of strength failed to move me. But Tor'gan used the hearts of the fleshstalkers to imbue me with spirits that conquered my doubt, freeing me.\n\nOur soldiers deserve the guile of the raptor. Collect the fleshstalker hearts for me, {name}.", sourceObjective = "Collect 12 Raptor Hearts from Highland Fleshstalkers.", progress = "My preparations are made, all I need are the raptor hearts.", completion = "As Tor'gan taught me, I transfer the power and the spirit of the raptors into this orb. It will imbue our warriors with the fiery strength and intelligence of the raptor.\n\nThe guile of the raptor is yours now as well, {class}. Take it with pride, for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26110] = { id = 26110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Like Old Times", description = "It's funny. Kin and I have been through so much together, and here we find ourselves back in Arathi, like so many years ago.\n\nWe broke up a plot to create a new plague right here, her and I. It doesn't look like the Horde learned their lesson, because they're all over this farm yet again.\n\nTheir undead courier is shuffling around as obvious as daylight. If you want to help, find the courier and bring back whatever they're carrying.", sourceObjective = "Collect the Sealed Folder from the Forsaken Courier.", progress = "We appreciate your help in looking for that courier, {name}.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Apothecaries yet again. You think they'd get the message. Let's see what it is this time...", sourceObjectiveStatus = "unverified-source-field" }
quests[26111] = { id = 26111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... It Will Come", description = "I now imbue you with the energies of the corrupting faceless.\n\nSwim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader.\n\nCall forth to Ick'thys the Unfathomable... it will come!", sourceObjective = "Obtain the Brain of the Unfathomable.", progress = "Do you have it, {name}?\n\nWith the Unfathomable's brain, we still may yet be able to communicate with L'ghorek, the dying ancient one in front of us.", completion = "And now we will see if we can get you into L'ghorek to speak with it before it dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26112] = { id = 26112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demanding Answers", description = "So just how did all those Dark Iron warriors end up here, on the doorstep of Ironforge, on the verge of invading our city?\n\nDoes not 'Empress' Moira, a member of our esteemed Council of Three Hammers, rule the Dark Iron? This cannot have happened without her knowledge and consent. This was no ragtag band of rebel dwarves, but a well-organized and fully equipped invasion force.\n\nI have prepared a report on the battle for the airfield. Take it to Ironforge, to the High Seat and confront her!", sourceObjective = "Take Stonebreaker's Report to Moira Thaurissan in Ironforge's High Seat.", progress = "What is the meaning of this intrusion?", completion = "And just what is this?\n\n<Moira takes the report and the color drains from her face as she reads.>\n\nThis is impossible!", sourceObjectiveStatus = "unverified-source-field" }
quests[26113] = { id = 26113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae and Kinelory", description = "The Horde have held Go'shek Farm to the east for a long time; it's never been of much concern compared to the rest of our problems here. But there's been reports of undead activity in the area.\n\nAnything more alarming than shuffling peons over there warrants investigation. This isn't the first time the undead have been up to no good at the farm, so I've sent my best scouts there to check it out. Report to Quae and Kinelory and they'll fill you in.", sourceObjective = "Find Quae on the hill overlooking Go'shek Farm.", completion = "Refuge Pointe sent you? Good to know they're still there.\n\nWe've got some interesting things to check into here, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26114] = { id = 26114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae Trusts You", description = "<Quae begins to go through the folder.>\n\nExpansion...control of territory... these undead aren't cooking up anything new, but they're planning to roll over all of Arathi. We need to disrupt their plans.\n\nI'll keep a lookout from up here. You go with Kin, and get those invasion plans. We're not going to let these walking corpses even know what day it is out here.\n\nAnd keep her safe, you hear me?", sourceObjective = "Speak to Kinelory near Go'Shek Farm in Arathi Highlands.", completion = "The plague took our friends and family, but it was the Forsaken that took Phin. They're just as bad as the Scourge. I'll destroy every one of them with my own hands if I have to.\n\nWhen you're prepared, come let me know. We'll get started right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[26115] = { id = 26115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Be Horde...", description = "Stand by me, {name}, and watch as our mighty weapon destroys our enemies!\n\nLearn what it means to be Horde!", sourceObjective = "Learn what it means to be Horde.", progress = "Now do you understand?", completion = "Now you truly know what it means to be a member of the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26116] = { id = 26116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinelory Strikes", description = "All right, {name}. I'm ready if you are.\n\nShall we?", sourceObjective = "Protect Kinelory until she returns to Quae.", progress = "You'd best keep with Kinelory. I trust you, but if something happens to her, I won't be accountable for my actions.", completion = "You've done a great service for us, {name}. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[26117] = { id = 26117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Southshore", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nRefuge Pointe will want to know of our success. I'm going to stay here with Kin and let her catch her breath. Go on ahead without us.", sourceObjective = "Return to Commander Amaren at Refuge Pointe.", completion = "I admit I'm impressed, {class}. It's a small comfort amidst all that's happened here.\n\nYou have fought the undead, struck back against the Horde, and honored the memory of the victims of Southshore. On behalf of the kingdom of Stromgarde, I present you with an official commendation, and this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[26118] = { id = 26118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seize the Ambassador", description = "The ambassador's betrayal will long haunt me. You must arrest him before he can do further harm, or worse, before he can escape and start planning the next attack. Ironforge is not safe with Ambassador Slaghammer free inside the city.\n\nTake these manacles and go to the Dark Iron embassy. It's just to the north of the High Seat, around the rim of the Great Forge. Arrest Ambassador Slaghammer and return with him.", sourceObjective = "Go to the Dark Iron Embassy and use the Sturdy Manacles to arrest Ambassador Slaghammer.", progress = "We must stop the ambassador before he causes more harm.", completion = "The ambassador will trouble us no more. He is not the only Dark Iron dwarf whose heart still belongs to Twilight's Hammer. We must remember that and remain vigilant against their schemes, else my son will inherit only ruins and ashes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26120] = { id = 26120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crazed Dragonmaw", description = "The Dragonmaw orcs nearby are fast becoming a nuisance. Their suicidal attacks on the grove are merely annoying, though they provide my sentinels with some needed practice.\n\nMy scouts, however, have seen them rounding up black dragon whelps in nets. The last thing these lands need is a crude revival of dragon-taming. Strike out to the east, {class}, and cut down the whelpstealers; make sure their folly does not come back to haunt us later.", sourceObjective = "Kill 12 Dragonmaw Whelpstealers.", completion = "The orcs will know better than to press further west now. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[26121] = { id = 26121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim Korthun's End", description = "You are seeink spies up above?  This is not good... not good at all, comrade.\n\nReturn to Korthun's End and destroy them, my friend.", sourceObjective = "Kill 7 Hellscream Seadogs in Korthun's End.", sourceObjectiveStatus = "unverified-source-field" }
quests[26122] = { id = 26122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Environmental Awareness", description = "Have you ever smelled submarine fuel, {name}?  It's nasty stuff.  Unfortunately, we need to burn huge amounts of it to get the Verne to move, and it's both bad-smelling AND deadly to the local wildlife.  We need to be more environmentally conscious.\n\nThe sea creatures nearby have particularly oily flesh.  Take this device up to Seabrush - just above this cave - and use it on the corpses of terrapins, remoras, and hammerhead sharks.  Their oil might save the lives of hundreds of other sea creatures.", sourceObjective = "Use the Oil Extrusion Pump on the corpses of Seabrush Terrapins, Scourgut Remoras, and Spinescale Hammerheads in Seabrush to obtain 4 Terrapin Oil, 4 Remora Oil, and 4 Hammerhead Oil.", progress = "Please... don't tell the other goblins that I'm an environmentalist!  I don't think I can take the mocking!", completion = "<Fiasco sticks a finger into each sample and sniffs it.>\n\nYes, I think this will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26124] = { id = 26124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure Seabrush", description = "The Alliance has spies in this area?  Tenebrous Cavern is nearby, and inside lies the Horde's new submarine, the Verne!  The Alliance must not be allowed anywhere nearby!\n\nSomeone in the cavern will want to hear of this incursion... after you finish slaying some more of these scheming Alliance spies.", sourceObjective = "Kill 7 Alliance Sea-Scouts in Seabrush.", completion = "You did well, {name}.  We need to be especially wary of Alliance attacks right now.  The Verne's got plenty of firepower out at sea, but in the back of this cave, she's far too vulnerable.", sourceObjectiveStatus = "unverified-source-field" }
quests[26125] = { id = 26125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure Seabrush", description = "You saw spies up above?  This is not good... I won't have it.\n\nReturn to Seabrush and get rid of them before they start trickling into our hideout.", sourceObjective = "Kill 7 Alliance Sea-Scouts in Seabrush.", sourceObjectiveStatus = "unverified-source-field" }
quests[26126] = { id = 26126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Fuel", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", sourceObjective = "Use the Fuel Sampling Station in Tenebrous Cavern to create the perfect bio-fuel.", progress = "We haven't found the right combination yet, {name}.  Keep at it!  I'm sure you can figure it out!", completion = "That's it.  Starting today, I'm shifting the Verne over to bio-fuel.  I'll send some men up to harvest more oil.\n\nThink of all the sea creatures that we've saved today, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26127] = { id = 26127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight's Hammer Revealed", description = "I and everyone else thought these fools were just Dark Iron up to no good, but these nutters are fullblown cultists!\n\nThe Twilight's Hammer wants nothing short of the destruction of the entire world. They've thrown their lot in with Deathwing and Ragnaros, and they've got a history with the Dark Iron.\n\nBut it doesn't matter who they are, what matters is they're in Dun Modr and they need to get out! I'll not let any past here. You get in there and crack some skulls!", sourceObjective = "Kill 12 Twilight's Hammer members in Dun Modr.", progress = "I've got to hold the line here, lad. As much as I want to get in there and tear them up, I'm dead set on making sure not a one of the slimy curs escapes!", completion = "Good show, lad, but we've no time to celebrate. Thandol Span's in danger!", sourceObjectiveStatus = "unverified-source-field" }
quests[26128] = { id = 26128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Thandol Span", description = "I've defended the Thandol Span from being destroyed before, against the Dark Iron themselves. And so did my father, and his father before him...\n\nThe only Dark Iron that managed to give me the slip ran straight for the bridge. Something's amiss, and I'm betting when we get there we'll be waltzing right into an ugly trap.\n\nI could use your help, {name}, for Ironforge. Are you with me?", sourceObjective = "Defeat Calamoth Ashbeard at the Thandol Span.", progress = "There's no time to waste! Hurry to the Thandol Span!", completion = "And good riddance!\n\nThandol Span's safe thanks to you, {name}, and hopefully Calamoth is down for good this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26129] = { id = 26129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers In Arms", description = "Listen, {name}.  For the first time since the civil war I agree with Greymane.  Now is the time to put aside our quarrel.\n\nIt sure doesn't look like these beasts care much whether you're a rebel or a royal.\n\nSend word back to Greymane.  My men will join his.\n\nThere's a safehouse not far from here, in Josiah's cellar.  My lads stashed some heavy artillery there.\n\nTell our king that my arsenals are now at his disposal.", sourceObjective = "Speak to King Genn Greymane at the Military District in Gilneas City.", completion = "Rebel arsenals?  In my own city?\n\nWhat in the bloody hell was Crowley up to?", sourceObjectiveStatus = "unverified-source-field" }
quests[26130] = { id = 26130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unplug L'ghorek", description = "L'ghorek is the ancient that rests upon the shelf across from us. It is being controlled and its life energies slowly consumed by something immense beneath us.\n\nThere is a cave known as the Undershell down below L'ghorek. In that cave are three powerful ogre magi that are maintaining a ritual connecting the thing below with the ancient. You must kill these three to disconnect L'ghorek.", sourceObjective = "Slay Ur'Goz, Sku'Bu, and Neph'Lahim.", progress = "You must slay each of those ogre magi to stop their rituals and disconnect L'ghorek from the one below.", completion = "Now that you have unplugged L'ghorek, we must attempt to make contact with it. I can sense that the ancient yet lives, but only barely.", sourceObjectiveStatus = "unverified-source-field" }
quests[26131] = { id = 26131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements for Loch Modan", description = "I've been waiting for the council to hear my plea for hours, and it's not looking good. Moira's greatest desire seems to be to paralyze the council.\n\nMeanwhile, Loch Modan suffers. Our enemies are many and our resources are few. Please, {name}, perhaps you will hear me if the council will not. Speak to Gryth Thurden, Ironforge's gryphon master. He's in the eastern part of the Great Forge. He'll provide a free flight to the South Gate Pass. Introduce yourself to Pilot Hammerfoot once you arrive.", sourceObjective = "Speak to Gryth Thurden at the Great Forge for a flight to Loch Modan. Speak with Pilot Hammerfoot when you arrive.", completion = "You don't know how glad I am to see fresh faces from Ironforge. Perhaps sending Mountaineer Barleybrew wasn't a waste after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26132] = { id = 26132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiends from the Netherworld", description = "The ogre magi within the Undershell have summoned protectors for themselves: fleshling fiends from the netherworld.\n\nWe cannot risk these aberrations from being later used against our forces. While you are in there, I want you to destroy as many of those things as you can.", sourceObjective = "Slay 8 Nether Fiends.", completion = "The last thing we needed was a bunch of summoned creatures swarming our forces during the final assault.", sourceObjectiveStatus = "unverified-source-field" }
quests[26133] = { id = 26133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiends from the Netherworld", description = "Those ogre magi inside the Undershell have summoned defenders: fleshling fiends from the netherworld.\n\nI do not want to see these aberrations used against our forces. While you are in there, destroy all of them!", sourceObjective = "Slay 8 Nether Fiends.", completion = "That's one less thing we need to think about during the final assault.", sourceObjectiveStatus = "unverified-source-field" }
quests[26134] = { id = 26134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Left for You Here", description = "There is nothing left for you here, {name}. As for me, I must lay Masha's body to rest. Once I have done that I will go to the bombing site and begin the process of regrowth. Perhaps one day a new grove will bloom - a grove infused with the spirit of my child and the fallen night elf youths.\n\nIf you wish to travel to Desolace, I hear word of a blood elf named Furien seeking adventuring partners. Perhaps you should seek him out.\n\nFarewell, friend, I will never forget you.", sourceObjective = "Speak to Furien at Tethris Aran in Desolace.", completion = "<Furien groans.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26135] = { id = 26135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", sourceObjective = "Witness the concluding story of the Battlemaiden by using her broken blade somewhere in the Temple of Quel'Dormir.", completion = "Minions of the Old God? Two very potent foes have joined forces then. Their hope to defeat the Tidehunter may not be so foolish after all.\n\n{name}, we can't let that happen. If Azshara defeats the Tidehunter and takes his power for herself, I'm not sure any number of us could ever hope to oppose her on the seas.\n\nThe first step is clear at least - we need to hunt down the fiend that destroyed our ships. The navy was confident enough to bring in a new fleet, perhaps they have a plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26137] = { id = 26137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking on the Boys", description = "I'm sure you've seen just how bad the damage to the Loch is by now. The damage spreads further than that, I'm afraid; all that water had to go somewhere, and it went down into the Wetlands.\n\nThere's a lot of fine dwarves down there trying to help out, and they need supplies. That's why I sent two of my mountaineers ahead with a cask of ale along the path into the Wetlands.\n\nI haven't heard back from them since they set off down the road to Dun Algaz. Would you mind checking up on them?", sourceObjective = "Travel to the Wetlands and speak to Mountaineer Rharen near Dun Algaz.", completion = "Ah, well met, {class}.\n\nStormpike sent you? About the keg? Hoo boy...", sourceObjectiveStatus = "unverified-source-field" }
quests[26138] = { id = 26138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferilon Leafborn", description = "There's a group of night elves that call the wetlands home now. A bunch of them shipped in from Kalimdor to study the land here, look at the plants, that sort of stuff.\n\nOne of the druids by the name of Ferilon stopped by here a while back. He was nice enough to give us a hand with some raptors, and he mentioned something about needing more folk to help out with his duties.\n\nIf you've got the time, you'll find him at the place they call Greenwarden's Grove, to the northeast.", sourceObjective = "Find Ferilon Leafborn at Greenwarden's Grove.", sourceObjectiveStatus = "unverified-source-field" }
quests[26139] = { id = 26139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Arathi", description = "You should go on ahead and warn the other side of the span about this, {name}.\n\nOver the bridge to the north you'll find Refuge Pointe, the stronghold of the Alliance in Arathi. Tell Captain Nials to keep an eye out for these Twilight's Hammer curs.", sourceObjective = "Travel to Arathi Highlands and speak with Captain Nials in Refuge Pointe.", completion = "I suppose I owe Thargas a favor for sending such a bold hero my way.\n\nOr perhaps he just wanted to keep all the clean-up for himself. Regardless, you'll find much to do here for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[26140] = { id = 26140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Communing with the Ancient", description = "Place the dead merciless one upon your head to pose as one of their slaves.\n\nEnter L'ghorek. Commune with the ancient.", sourceObjective = "Deliver the Brain of the Unfathomable to L'ghorek in the Cerebrillum inside of L'ghorek in Vashj'ir.", progress = "I SENSE... SOMETHING. COME CLOSER....", completion = "WISE OF... YOUR ERUNAK TO... HAVE... YOU USE... THE FACELESS' BRAIN. I SEE... YOU NOW.\n\nI WILL DIE. THERE IS NO... STOPPING... THE INEVITABLE.\n\nBUT... YOU WILL HELP... ME DEAL WITH... THESE PARASITES FIRST.", sourceObjectiveStatus = "unverified-source-field" }
quests[26141] = { id = 26141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runestones of Binding", description = "ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION.\n\nWE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.", sourceObjective = "Collect 7 Runestones of Binding.", progress = "DO... YOU HAVE... ALL THAT IS... REQUIRED?", completion = "WE WILL USE... THESE... RUNESTONES TO ALLOW... YOU TO POSSESS... ONE OF... THE WATER ELEMENTALS.", sourceObjectiveStatus = "unverified-source-field" }
quests[26142] = { id = 26142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascend No More!", description = "TO STOP... THEIR... RITUALS OF ASCENSION... YOU MUST DESTROY... THE ANCIENT CONDUITS.\n\nTHEY USE... THE CONDUITS TO... SIPHON... MY ENERGIES AWAY... AND MAKE... ASCENDANTS.\n\nA FIGHT WITH... NEPTULON IS IMMINENT. THE TWILIGHT'S HAMMER... MUST BE DENIED... THESE CREATURES.", sourceObjective = "Destroy 5 Ancient Conduits.", completion = "THEY SHALL ASCEND... NO MORE!", sourceObjectiveStatus = "unverified-source-field" }
quests[26143] = { id = 26143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All that Rises", description = "<The voice of the ancient presses against your mind.>\n\nNOW THAT... YOU HAVE STOLEN... THE ENERGIES OF... THE FAITHFUL, ENTER... THE TEMPLE AND... DESTROY... HALLAZEAL THE ASCENDED!", sourceObjective = "Slay Hallazeal the Ascended.", completion = "YOU HAVE DONE... MYSELF AND... THE TIDEHUNTER GREAT... SERVICE.", sourceObjectiveStatus = "unverified-source-field" }
quests[26144] = { id = 26144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Alliance prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!You will be able to choose one of these rewards:", sourceObjective = "Rescue 5 Alliance Prisoners.", sourceObjectiveStatus = "unverified-source-field" }
quests[26145] = { id = 26145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trogg Threat", description = "{class}, you may or may not be aware of the trogg threat looming over dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we're left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the town here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned troggs lurking in the hills.  If you're up to the task, wage an assault on the troggs.  Bring me back eight trogg stone teeth as proof.", sourceObjective = "Collect 8 Trogg Stone Teeth.", progress = "Do you have eight trogg stone teeth to show me?  If not, there is still work to be done, {name}.", completion = "I am quite impressed, {name}.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!", sourceObjectiveStatus = "unverified-source-field" }
quests[26146] = { id = 26146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the King's Lands", description = "We need to protect the Loch, {name}! With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front. Troggs are tunneling up from every crevice! The trogg infestation poses the largest threat to Ironforge.\n\nWe need you, brave adventurer, to venture forth and lay waste to the trogg threat. Slay twelve Stonesplinter troggs and venture back.", sourceObjective = "Kill 12 Stonesplinter Troggs or Stonesplinter Scouts.", completion = "Well done, {name}!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26147] = { id = 26147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger and Uglier", description = "The Mountaineers tell me you are quite brave and capable, {name}.  We need a {race} like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned {class} here, let's see what you can do.\n\nGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.\n\nLet's see if you live up to your reputation, Trogg-Slayer.", sourceObjective = "Kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers.", progress = "Back so soon?  In case I didn't make myself clear we need you to kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers, {name}.  Now go get 'em, Trogg-Slayer!", completion = "I knew the second I laid eyes on you, {name}, that you would make Ironforge proud.  You have served our people well. I salute you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26148] = { id = 26148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Decisive Strike", description = "It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. He's the biggest of all the troggs here, lurking deep within the darkness of the caves to the north.\n\nIf you feel yourself worthy, {name}, I want you to lead the assassination mission on Grawmug.", sourceObjective = "Kill Grawmug.", progress = "Your mission is not complete until Grawmug has been brought to death.  Khaz Modan is counting on you, {name}.", completion = "Most excellent, {name}! You have brought hope to Loch Modan. With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[26149] = { id = 26149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Horde prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!You will be able to choose one of these rewards:", sourceObjective = "Rescue 5 Horde Prisoners.", sourceObjectiveStatus = "unverified-source-field" }
quests[26150] = { id = 26150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With Maybell", description = "You seem like the helpful type, {name}. How about doing an old man a favor?\n\nThe last time I was over at the Maclure Vineyards I overheard Maybell crying in her cottage. Would you be so kind as to go check up on her? I'm a little worried.", sourceObjective = "Speak to Maybell Maclure at the Maclure Vineyards in Elwynn Forest.", completion = "William sent you? Bless his soul. I... I'm ok... It's just... Well...", sourceObjectiveStatus = "unverified-source-field" }
quests[26152] = { id = 26152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: James Clark", description = "By decree of the Stormwind Army, a bounty has been placed on the head of James Clark.\n\nClark is wanted for robbery, burglary, arson, and murder. He is also a suspect in the kidnapping and disappearance of the Brackwell's prized pig, Princess.\n\nJames Clark was last seen heading towards Eastvale Logging Camp.\n\nBring James Clark to justice and report to Marshal McCree at Eastvale Logging Camp.", sourceObjective = "Kill James Clark and take James Clark's Head.", progress = "Turning in a bounty?", completion = "And justice is served!", sourceObjectiveStatus = "unverified-source-field" }
quests[26153] = { id = 26153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penny's Pumpkin Pancakes", description = "My daughter Penny loves pumpkin pancakes but we have had a shortage of pumpkins here in Elwynn from the frostbite last season.  I have heard of a new pumpkin patch north of Stormwind that might be ripe for the picking now though.  Head out and harvest a few of those ripe pumpkins for me and let's see what we can do.", sourceObjective = "Obtain 6 Stormwind Pumpkins. Deliver them to Robby Flay in Stormwind City.", progress = "Have you finished collecting the pumpkins?", completion = "Nice job, {name}! Penny will be very excited for breakfast tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[26154] = { id = 26154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Extermination", description = "NOW, TAKE... THE ATTUNED RUNESTONE... AND USE... IT TO POSSESS... ONE OF... THE BOUND TORRENTS... AT... THE CENTRAL TEMPLE. THEY WILL IGNORE... YOU. YOU ARE BENEATH... THEIR NOTICE.\n\nUSE... THE ELEMENTAL'S POWERS... TO DESTROY... THE TWILIGHT DEVOTEES... AND... THEIR... FACELESS OVERSEERS.", sourceObjective = "Possess a Bound Torrent and then slay 50 Twilight Devotees and 10 Faceless Overseers.", sourceObjectiveStatus = "unverified-source-field" }
quests[26157] = { id = 26157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasim Sharim", description = "I need you to pass on a message for me.\n\nKasim Sharim is an old blood mage that knows a great deal about the demons of the Blasted Lands.  Though you wouldn't know from looking at him, he's quite old, and very powerful... if a little eccentric.  As of late, he spends his days in the back of the Serpent's Coil, a cave not far from where you killed those cultists.\n\nPlease, deliver this message to him.  He will know what it means.", sourceObjective = "Report to Kasim Sharim in the back of the Serpent's Coil in the Blasted Lands.", progress = "I don't know you.", completion = "Hah!  You Nethergarde nincompoops are always two steps behind me, and I'm nowhere near as fast as I used to be.\n\nI don't need Mahar's note to know what's going on.  Why do you think I'm cooped up in the back of this cave?  What I do need, however, is a strong {race} like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26158] = { id = 26158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attune the Bloodstone", description = "Did you have fun fighting your way to the back of this cave?  I admit, I haven't picked the most... convenient of spots to perform my studies, especially for passing adventurers who wish to enter and leave at will.\n\nHowever, I can allow you to attune yourself to my bloodstone teleporters.  Simply place your hands on the stone in the back corner, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", sourceObjective = "Attune yourself to the Bloodstone Teleporters in the Serpent's Coil.", completion = "Excellent!  You've managed to complete the simplest of tasks without dying.  Now that that's out of the way...", sourceObjectiveStatus = "unverified-source-field" }
quests[26159] = { id = 26159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "Like any good bloodmage, I perform my magic with blood.  All blood is different, and the Blasted Lands has several useful flavors, if you know where to look.\n\nFor our purposes?  Basilisks and hyenas, even amounts.  We're going to need plenty of it.  Head west, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", sourceObjective = "Obtain 9 vials of Snickerfang Hyena Blood and 9 vials of Redstone Basilisk Blood.", progress = "Do you have it?", completion = "<Kasim eyes the blood hungrily.>\n\nMore than enough, and still warm!  Now, let's get this ritual started, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[26160] = { id = 26160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Ritual", description = "I suppose you want to know what we're doing.  Here's the short version - a version at which I happen to be an expert:\n\nThe Shadowsworn cultists wish to summon the demon, Razelikh, back to the Blasted Lands.  We cannot allow this to happen.  So we're going to summon him ourselves, and then kill him.  A task not as simple as it sounds...\n\nLet me know when you are ready to begin the blood ritual, and then stand back.", sourceObjective = "Speak with Kasim Sharim to begin the blood ritual.", progress = "The ritual is not yet complete.", completion = "The blood ritual was a success; I can clearly see where we are going next.\n\nI'm sorry, I misspoke.  What I meant to say is, I can see where YOU are going next...", sourceObjectiveStatus = "unverified-source-field" }
quests[26161] = { id = 26161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Just Any Body", description = "We need Loramus Thalipedes, the demon hunter.  He knows Razelikh's true name, and as you know: if you know the name of the demon, you have power over it.  The problem is that Loramus has been killed, and his body torn apart.\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are in the west... the Dreadmaul ogres hide them in their caves.  Move quickly, for much like Grimeo, Loramus also owes me a debt...", sourceObjective = "Find Loramus' Head, Loramus' Torso, and Loramus' Legs.", progress = "Trust me... whatever happened to Loramus, we can fix.  The limits of blood magic are still undefined.", completion = "I see... yes, I can work with this.\n\n<Kasim looks at the night elf's head.>\n\nLoramus Thalipedes, demon hunter.  I look forward to our reunion.", sourceObjectiveStatus = "unverified-source-field" }
quests[26162] = { id = 26162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Storms", description = "Up on the bluffs to the west lies a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", sourceObjective = "Bring Loramus' Body to the Altar of Storms, then protect it while the ritual completes.", completion = "You... you fool!  What have you done?", sourceObjectiveStatus = "unverified-source-field" }
quests[26163] = { id = 26163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is Short", description = "Razelikh plans to return to the Blasted Lands and overwhelm Azeroth with his demons.  Even now, he is preparing to summon his legions to eliminate us.  With these three amulets, we have the method to summon him... but no way to destroy him.\n\n<The gnome quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Grimeo at the Dark Portal, to the southeast.  He will guide you.  Quickly!  Time is short!  And so am I!", sourceObjective = "Deliver the Discordant Rune to Watcher Grimeo at the Dark Portal in the Blasted Lands.", progress = "Do I know you, good {race}?", completion = "No, no, no... not Kasim again!  This is madness!\n\nPlease, remain quiet.  If my commander learns that I still work for the short one, do you know how quickly I will be removed from the watch?\n\n<Grimeo takes the rune from you, presses it to his chest, closes his eyes, and sighs.>\n\nI see you speak the truth.  Let us begin our business quickly, so that it may end even quicker.", sourceObjectiveStatus = "unverified-source-field" }
quests[26164] = { id = 26164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charred Granite of the Dark Portal", description = "Kasim wants you to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", sourceObjective = "Obtain 24 Charred Granite Chips.", progress = "Please, lower your voice.", completion = "I hope this is what the gnome wanted.", sourceObjectiveStatus = "unverified-source-field" }
quests[26165] = { id = 26165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Blood of Demons", description = "Sharim wants demon blood.  Speaking personally, the stuff does not even seem like blood to me - more like liquid rot - but that is of no consequence.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", sourceObjective = "Obtain 7 bottles of Vile Demonic Blood.", progress = "Ugh, what's that smell?  Is that you, or the blood?", completion = "There is no doubt about it, you have found demon blood.\n\nKasim's requests aside, I am sure that my Watch Commander is thankful for your efforts.  They have been struggling to deal with these demon distractions for some time now.", sourceObjectiveStatus = "unverified-source-field" }
quests[26166] = { id = 26166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing the Stone", description = "<Grimeo finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that the gnome asked of us.  When you see him, make sure you let him know that this task ends my debt.  I will not suffer his requests any longer.", sourceObjective = "Bring Grimeo's Package to Kasim Sharim at the Serpent's Coil in the Blasted Lands.", progress = "You've returned, {class}.", completion = "This is sufficient.  If you see Grimeo again, you may tell him that he performed satisfactorily, but no... his debt is not yet cleared.  I will get to work on fashioning the stone knife of sealing.  There is no need for questions now.  All will be revealed in time.\n\nWhile I work, I have another task for you to complete.\n\nDon't look so upset!  This task will be fun... it involves collecting body parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[26167] = { id = 26167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Allistarj", description = "To summon our demon, we need three amulets, and the first is the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside this very cave.  Along with the other amulets, this relic will give us access to Razelikh's perch.\n\n<Kasim concentrates for a moment.>\n\nThe amulet is close to the entrance.  I recommend using the teleporter.", sourceObjective = "Obtain the Amulet of Allistarj from the Serpent's Coil in the Blasted Lands.", progress = "Allistarj left a piece of himself in that amulet.  Even now, I can sense his evil.", completion = "<Kasim examines the amulet.>\n\nHe was an archmage, I can feel it.  I will hold the amulet for you while you collect the rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26168] = { id = 26168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Sevine", description = "The second amulet, Sevine's amulet, is in the hands of a murloc, far to the south, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nBring her amulet to me, along with the rest.", sourceObjective = "Obtain the Amulet of Sevine from Salt-Flop near the Shattershore in the Blasted Lands.", progress = "Sevine's amulet... along with the others, we can summon the Defiler.", completion = "<Kasim hefts the amulet.>\n\nA warlock... and a powerful one at that.  I will hold onto this until the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26169] = { id = 26169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Grol", description = "Grol... the ogre.\n\n<Kasim laughs.>\n\nIt would seem that Grol's body no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", sourceObjective = "Obtain Grol's Amulet from the Shattershore in the Blasted Lands.", progress = "The third amulet, from Razelikh's third lieutenant.", completion = "<Kasim clutches the third amulet.>\n\nHe was a powerful warrior, this one.  I will keep the amulet until we are ready to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26170] = { id = 26170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Ritual", description = "The knife is ready.  Loramus is present, and he knows what he must do.  I must now take the three amulets and use their enchantment to grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", sourceObjective = "Speak with Kasim Sharim and participate in his ritual.", progress = "Quickly, friend.  This is but the calm before the storm.", completion = "It would seem that we are prepared to face our demon, {name}.  We have the amulet's blessing, we have the stone knife, and I alone know the demon's true name: Rakh'likh.  Together, this may be enough to defeat the Defiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[26171] = { id = 26171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Rakh'likh, Demon", sourceObjective = "Speak with the Deathly Usher north of the Rise of the Defiler. Once atop the Rise, destroy Razelikh's body, then use the Stone Knife of Sealing to imprison his soul.", completion = "Loramus, resurrected!?  And then he trapped the demon inside his own body... by the Light...\n\nI see.  So this was Kasim's plan all along.  I suspected correctly, but I suppose I refused to believe it.\n\nAh, one last thing!  Kasim left one more instruction for me within his rune.  I did not understand it at first, but given the events that have taken place today, it now makes much more sense:\n\nHe asked me to let you choose from one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[26172] = { id = 26172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, ancient and powerful bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of a hostile cultist stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help me replenish my ever-dwindling foodstores?", sourceObjective = "Obtain 5 Ashmane Steaks from Ashmane Boars in the Blasted Lands.", progress = "I'm famished!  If you don't hurry, I might actually resort to drinking our reagents.", completion = "These are perfect, {name}.  I will eat well for the next several days.", sourceObjectiveStatus = "unverified-source-field" }
quests[26173] = { id = 26173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Rear", description = "The only reason you see me standing aside Horde soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", sourceObjective = "Kill Jarroc Torn-Wing, Shahandana, and Gomegaz.", progress = "You have not yet killed these demons.  {name}!  Get back to the field!", completion = "Your work is appreciated, soldier.\n\n<The commander leans in close, and whispers:>\n\n{race}... if you're still interested, I have one more small task for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[26174] = { id = 26174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watching Our Back", description = "<Watch Commander Relthorn Netherwane speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Horde periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", sourceObjective = "Examine the Horde Plans at the Dark Portal without getting caught.", progress = "Did you get a look at those plans, {name}?", completion = "You're certain nobody saw you?  Good.\n\n<Netherwane listens to your recount of the information you saw.>\n\nHmph... fairly harmless stuff.  Either the Horde are foolish enough to NOT be planning something against us... or they're hiding their information better than I expected.  Either way, well done, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[26175] = { id = 26175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surwich", description = "Other than what you've seen, the Portal's been surprisingly quiet.  There isn't much more work I can give to you, I'm afraid.\n\nIf you're looking for trouble, you might try the Gilnean fishing village to the southwest.  Surwich, I think it was.\n\nI know we're supposed to be friends with the Gilneans, but really?  Worgen?  I had enough trouble getting used to the draenei.", sourceObjective = "Report to Mayor Charlton Connisport at Surwich in Blasted Lands.", completion = "Welcome to Surwich, {race}.  Please, have a look around.", sourceObjectiveStatus = "unverified-source-field" }
quests[26176] = { id = 26176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Thelsamar", description = "You've helped us quite a bit here. If you're leaving, I'd ask you to take this status report up to Thelsamar.\n\nFollow the road just north, and you can't miss it. Mountaineer Kadrell will want the report.", sourceObjective = "Deliver Captain Rugelfuss's Status Report to Mountaineer Kadrell in Thelsamar.", progress = "What can I do for you?", completion = "Glad to hear you've been clearing out the troggs. Let's have a look at this report, and...\n\n...Is that a beer stain?", sourceObjectiveStatus = "unverified-source-field" }
quests[26177] = { id = 26177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Crabby?", description = "Fresh crab legs have always been one of the King's favorite foods.  We have had good luck catching fresh crabs in the canals over the past few weeks.  Do you think you can lend me a hand and catch a few of them for me?  Be sure to catch them alive, they are no good to me dead, the King requires the freshest catch we can muster.", sourceObjective = "Catch 6 Canal Crabs. Deliver them to Robby Flay in Stormwind City.", progress = "You must have fast hands!  I can't believe you caught all those crabs so quickly!", completion = "These crabs look great!  I will clean these up and make sure that the King hears about your contribution.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[26178] = { id = 26178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", sourceObjective = "Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26179] = { id = 26179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", sourceObjective = "Kill 7 Venture Co. Workers for Morin Cloudstalker at Bloodhoof Village.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the {race} lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26180] = { id = 26180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", sourceObjective = "Kill Supervisor Fizsprocket and collect Fizsprocket's Clipboard.", progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26181] = { id = 26181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Darkbreak Cove", description = "YOU MUST RETURN... TO... THE DARKBREAK COVE. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", sourceObjective = "Speak with Erunak Stonespeaker at Darkbreak Cove in Vashj'ir.", completion = "Hello again, {class}.\n\nI felt L'ghorek die. A shame that such a magnificent being is gone.\n\nIf we do not assist Neptulon, we will all meet the same fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[26182] = { id = 26182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Tenebrous Cavern", description = "YOU MUST RETURN... TO... THE TENEBROUS CAVERN. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", sourceObjective = "Speak with Erunak Stonespeaker at the Tenebrous Cavern in Vashj'ir.", completion = "Hello again, {class}.\n\nI felt L'ghorek die. A shame that such a magnificent being is gone.\n\nIf we do not assist Neptulon, we will all meet the same fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[26183] = { id = 26183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Cider", description = "I am forever in debt to our King for all that he has done for us.  One thing I can do for him is make his favorite drink!  Lucky for us, the ingredients we need to make this wonderful drink are located right here in Stormwind City.  Apple trees can be found in every district of Stormwind.  These trees are too tall to pick the fruit from, but lucky for us the apples have fallen to the ground and are easy to retrieve.", sourceObjective = "Obtain 12 Juicy Apples. Deliver the fruit to Robby Flay in Stormwind City.", progress = "Were you able to find enough juicy apples?", completion = "These will do nicely {name}.  I will get to work right away on the cider.", sourceObjectiveStatus = "unverified-source-field" }
quests[26184] = { id = 26184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wormthorn's Dream", description = "Not surprisingly, most of our citizens in Surwich did not come to the Blasted Lands for the pleasant atmosphere.  They came following the dream of an idealistic druid: Marl Wormthorn.  Wormthorn believed that the Tainted Scar could be healed, and attempted to grow it back.\n\nIt looks like he was wrong.  He grew his forest, but the land is still plagued by demons, and his great-tree is twisted and gnarled.\n\nI'm still hopeful.  Maybe if we head into the Tainted Forest and clear out some of the taint...", sourceObjective = "Kill 5 Doomguard Destroyers, 5 Dreadlord Defilers, 5 Corrupted Darkwood Treants, and 3 Felspore Bog Lords in the Tainted Forest.", progress = "<Charlton is thinking to himself.>\n\nMarl, what have we done?", completion = "You say the demons were all worshipping the tree?\n\n<The mayor sighs.>\n\nIt is as I feared, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[26185] = { id = 26185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advice from the Cenarion Circle", description = "I believe that the taint of the Blasted Lands has finally exerted its influence over my friend Wormthorn.  His experiment has failed, and his great-tree now only serves as a focus for the demons to rally around.\n\nThe tree must come down, and Wormthorn with it.  Speak with the Cenarion Observer on the other side of town; she should have some idea how to proceed.\n\n{name}: the act we are about to commit must not be made known to the townspeople of Surwich.  Morale is low enough as-is.", sourceObjective = "Report to Cenarion Observer Shayana at the Surwich in the Blasted Lands.", completion = "While I'm surprised that Connisport is willing to go forward with his plan, I'm also relieved.  I've seen the demons rallying around Maldraz, and I share his fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[26186] = { id = 26186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", sourceObjective = "Kill the Tainted Black Bears, Tainted Nightstalkers, and Tainted Screechers in the Tainted Forest, and try to assemble their parts into a Demoniac Vessel.", progress = "Shayana's plan is a good one.  Do you have the vessel, {name}?", completion = "<Mayor Charlton Connisport looks warily at the device you've assembled.>\n\nVery well, {name}.  We have what we need to break Marl's trance and put an end to both him and his experiment.", sourceObjectiveStatus = "unverified-source-field" }
quests[26187] = { id = 26187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Downfall of Marl Wormthorn", description = "When word gets out about what we've done... there's no saying what the citizens of Surwich will do.  They cling so closely to Wormthorn's dream...\n\n...but still, it must be done.  Take the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", sourceObjective = "Kill Marl Wormthorn at Maldraz in the Blasted Lands. You can use the Demoniac Vessel to pull him out of his trance.", progress = "Get back out there, before I change my mind.", completion = "Thank you, {name}.  I, and the people of Surwich, are in your debt.\n\nFeel free to take one of these.  While we haven't got much, we're happy to reward those that protect us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26188] = { id = 26188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I have gathered all the parts of the remedy I need to cure myself... except a flatland cougar femur.\n\nI grow weaker by the moment... please, help me.", sourceObjective = "Bring a Flatland Cougar Femur to Maur Raincaller at Bloodhoof Village.", progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, {name}. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[26189] = { id = 26189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Angerfang Menace", description = "When we hauled up here to get away from the raptors, we put ourselves right next to a whole slew of Dragonmaw orcs!\n\nI've heard the stories in Menethil, how the Dragonmaw are even cruder barbarians than other orcs, how they strangle black dragons with their bare hands... I don't know how much of it's true, but I know we can't just let 'em sit up here in the hills.\n\nYou've got the chops for it, {name}. Head east to the Angerfang Encampment, take care of those orcs, and make sure you get their leader!", sourceObjective = "Slay Gorfax Angerfang and 16 Dragonmaw Orcs in the Angerfang Encampment.", completion = "Good to see you back in one piece, {name}! You're quite a piece of work.\n\nI'll be tellin' Captain Stoutfist how you took care of those orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[26190] = { id = 26190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fisherman's Feast", description = "If there is one meal I know the King likes, it's fresh catfish.  Catfish are easy to prepare but hard to catch.  That's where you come in!  We have a good population of gigantic catfish here in the waters of Stormwind but the competition to catch them is intense to say the least.  I need you to figure out a way to \"acquire\" some of these fine catfish for our King.  You will find fishermen at the small canal docks around town.  You should be able to figure out the rest of the plan on your own.", sourceObjective = "Obtain 5 Gigantic Catfish. Deliver the fish to Robby Flay in Stormwind City.", progress = "Were you able to steal the fish?", completion = "Thank you, {name}.  I will get to work scaling these for the King right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[26191] = { id = 26191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culmination of Our Efforts", sourceObjective = "With every day, more warriors arrive at Azshara's command. Soon, Neptulon the Tidehunter will hear of our preparations, but too late to stop what we have set in motion. Our numbers will be too great and our allies too powerful. Victory is only a matter of time.\n\nIn Azshara's name.", sourceObjectiveStatus = "unverified-source-field" }
quests[26192] = { id = 26192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orphans Like Cookies Too!", description = "The orphans of Stormwind are often forgotten, but not today my friend.  The king has requested a special batch of cookies be baked and sent immediately over to the orphanage.  I was almost finished with the final batch when I ran out of confectioners' sugar.  Can you run out and get some more for me?  You should be able to find it at any of the general stores or inns inside of Stormwind.", sourceObjective = "Obtain 4 sacks of Confectioners' Sugar. Deliver the sugar to Robby Flay in Stormwind City.", progress = "Were you able to find the confectioners' sugar?", completion = "These sacks look like just enough, {name}.  Can't wait to see the smiles on the orphans' faces.", sourceObjectiveStatus = "unverified-source-field" }
quests[26193] = { id = 26193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nWe cannot stand idly by while the naga threaten Neptulon's realm.\n\nMake ready! With this submarine and its armaments, perhaps we can make a difference.\n\nSpeak to me when you are prepared for battle.", sourceObjective = "Speak to Erunak in Darkbreak Cove to enter the battle for the Abyssal Breach.", completion = "NO!\n\nThis is NOT over!", sourceObjectiveStatus = "unverified-source-field" }
quests[26194] = { id = 26194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nWe cannot stand idly by while the naga threaten Neptulon's realm.\n\nMake ready! With this submarine and its armaments, perhaps we can make a difference.\n\nSpeak to me when you have made your preparations.", sourceObjective = "Speak to Erunak in Tenebrous Cavern to enter the battle for the Abyssal Breach.", completion = "They may think they've won, but my axe and I have something to say about that!", sourceObjectiveStatus = "unverified-source-field" }
quests[26195] = { id = 26195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Wards The Greenwarden", description = "The greenwarden was a local legend. Many thought him a myth... the plant-man, protector of the wetlands. The night elves came here just to find him, and after they succeeded they ended up settling down to the east.\n\nThey've got a whole grove over there to watch over the greenwarden, and I've heard he's been acting up, enraged by the flooding and damage to the land.\n\nThe elves are good people. They could use the help of someone like you. If you get a chance, go tell the head druid what you've done here.", sourceObjective = "Talk to Ferilon Leafborn at Greenwarden's Grove in the Wetlands.", completion = "Welcome to the Greenwarden's Grove, {class}. I am glad Whelgar has told you of us.\n\nIf you are able to lend us your assistance, I will be most grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[26196] = { id = 26196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longbraid the Grim", description = "The dwarves of Dun Modr fight day and night against the Dark Iron that have invaded their old home. While we cannot yet send our sentinels to risk their lives for them, we do send much needed supplies that they may sustain their vigil.\n\nIf you would, bring this package to Longbraid the Grim, north of here. His men must certainly need its contents.", sourceObjective = "Take Ferilon's Care Package to Longbraid the Grim at Dun Modr.", progress = "Aye, what've ye got for me?", completion = "Supplies from Ferilon? Bless his heart.\n\nWe're good on food, but we're runnin' out of bullets!", sourceObjectiveStatus = "unverified-source-field" }
quests[26197] = { id = 26197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque has assembled a team of trainers to help you learn your arts.\n\nBipsi Frostflinger will help oversee your training and adjustment to life on the surface. She's waiting for you outside the tall building to the northeast.", sourceObjective = "Meet with Bipsi Frostflinger in New Tinkertown.", completion = "{name}, isn't it? It's a pleasure to finally meet you. While you were getting cleaned up, Nevin's team told me about your escape from Gnomeregan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26198] = { id = 26198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Mage", description = "I want to show you a simple technique. It will allow you to focus and channel bursts of arcane power toward an opponent.\n\nAs you grow in power, you'll learn how to add more and more missiles to each volley.\n\nFind one of the training dummies setup in the middle of town. You won't always be able to cast arcane missiles right away. First, you'll need to cast other spells at the dummy until you've created an opportunity to use arcane missiles. Try it out for yourself.", sourceObjective = "Speak to Bipsi Frostflinger to train Arcane Missiles. Once you've learned the spell, successfully cast Arcane Missiles twice at a Training Dummy in New Tinkertown.", completion = "You picked that one up quickly. I can't wait to show you some of my other favorite tricks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26199] = { id = 26199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\n\"Doc\" Cogspin will help oversee your training and adjustment to life on the surface. She's waiting for you near the cluster of buildings to the north.", sourceObjective = "Meet with \"Doc\" Cogspin in New Tinkertown.", completion = "It's good to meet you, {name}. I'm sure your time in Gnomeregan afforded you ample opportunity to practice your arts. Things are somewhat safer here, but your talents will never go to waste.", sourceObjectiveStatus = "unverified-source-field" }
quests[26200] = { id = 26200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Priest", description = "I have a simple technique I want to show you. It's pretty straightforward, but it's still one of the most useful things I know.\n\nYou can use it to heal yourself or a wounded ally very quickly. It's handy for when you need to treat someone promptly and don't have time for something more complicated.\n\nGive it a try for yourself and let me know when you think you have it mastered.", sourceObjective = "Speak to \"Doc\" Cogspin to train Flash Heal. Use Flash Heal 5 times on Wounded Infantry in New Tinkertown.", completion = "Good work, {name}. You have a natural talent for our arts.", sourceObjectiveStatus = "unverified-source-field" }
quests[26201] = { id = 26201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of a Warlock", description = "I'm not at all surprised that a warlock like you fought your way out of Gnomeregan. Few people, even among the gnomes, truly understand the nature of the power we wield.\n\nLet me show you a conjuration that I find handy. This spell, called Immolate, sets your target aflame, causing damage immediately and over time. Use it well, {name}, and your enemies will come to fear you.", sourceObjective = "Speak to Alamar Grimm and learn Immolate, then cast Immolate on a Training Dummy in New Tinkertown 5 times.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26202] = { id = 26202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. We're going to need all the help we can get to reclaim our home and rid ourselves of the troggs and irradiated gnomes. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your, uh, \"arts\".\n\nAlamar Grimm has taken up residence in the building just west of this one. He possesses powers similar to yours and can help you get adjusted.", sourceObjective = "Meet with Alamar Grimm in New Tinkertown.", completion = "So, another one of Nevin's \"rescued\" survivors, eh? More than likely, you saved his life from the troggs down there. Did he stumble over his words when he mentioned me? The man has a healthy respect for the demonic powers we channel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26203] = { id = 26203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nDrill Sergeant Steamcrank will help oversee your training and adjustment to life on the surface. He's waiting for you on the small practice field across the road.", sourceObjective = "Meet with Drill Sergeant Steamcrank in New Tinkertown.", completion = "For a {race} who has spent so much time inside Gnomeregan, you look positively fit and healthy, {name}. That's good. Before we can complete what Operation: Gnomeregan began, we're going to need more warriors like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26204] = { id = 26204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Warrior", description = "I want to show you a simple but useful technique.\n\nAs I tell all my recruits, a warrior who strikes first can use that momentum to gain the upper hand. This is a technique to use from a distance, before engaging your opponent. It will allow you to charge in, taking your enemy by surprise and stunning him.\n\nTry it out. Let me know when you think you've mastered it.", sourceObjective = "Speak to Drill Sergeant Steamcrank to learn Charge. Locate a Training Dummy in New Tinkertown and use Charge on it.", progress = "By making the first move in combat, you'll give yourself an early advantage.", completion = "Good work! Keep practicing your charge and you'll have an instant advantage at the start of battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[26205] = { id = 26205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job for the Multi-Bot", description = "If the multi-bot works, it will help us do all kinds of jobs that are unpleasant or dangerous for us gnomes!\n\nAfter Thermaplugg detonated his irradiator at the end of Operation: Gnomeregan, toxic clouds and ooze began bubbling up at the old airfield south of town.\n\nIf we don't get it under control, the contamination could spread to the rest of our lands. Take the multi-bot with you, and bring it close to the geysers in the green pools at the Toxic Airfield. Your bot should spring into action!", sourceObjective = "Use the GS-9x Multi-Bot to clean up 5 Toxic Geysers at the Toxic Airfield. When you get close enough to a geyser, your GS-9x Multi-Bot will automatically begin its task.", completion = "Wow, I never expected it to work on the first trial!\n\nUh, I mean, we've succeeded! I wonder what other uses I we can find for this handy little guy.", sourceObjectiveStatus = "unverified-source-field" }
quests[26206] = { id = 26206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nKelsey Steelspark, a key member of Gnomeregan Covert Ops, will help oversee your training and adjustment to life on the surface. She should be in the council tent to the northwest.", sourceObjective = "Meet with Kelsey Steelspark in New Tinkertown.", completion = "It's good to meet you, {name}. Nevin tells me that you managed to survive the dangers in Gnomeregan by using your wits. That's exactly what we need up here. Clever minds and quick blades.", sourceObjectiveStatus = "unverified-source-field" }
quests[26207] = { id = 26207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Rogue", description = "I have a technique I want to show you.\n\nOne of a rogue's most potent abilities is to chain together moves in a combination, exploiting your enemy's weakness and opening up the opportunity to use stronger maneuvers. The technique I want to teach you is called Eviscerate. It is intended for use at the end of a combination to provide a strong finish to your assault.\n\nTry using it after a landing a couple of Sinister Strikes.", sourceObjective = "Speak to Kelsey Steelspark to learn Eviscerate, then find a training dummy in New Tinkertown and practice using Eviscerate 3 times.", progress = "As you progress in skill, you will learn more techniques that allow you create combinations of deadly maneuvers.", completion = "I'm not surprised to see you're such a quick study. I look forward to showing you more of our tricks of the trade.", sourceObjectiveStatus = "unverified-source-field" }
quests[26208] = { id = 26208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fight Continues", description = "The dwarves of Ironforge kindly took us in when the trogg invasion and radiation forced us to leave Gnomeregan for the first time. But even the kindness of friends can't quell the longing for home.\n\nI sent out a call for brave gnomes and other members of the Alliance to help us regain control of Gnomeregan and defeat the usurper Thermaplugg once and for all.\n\nWe weren't able to achieve everything Operation: Gnomeregan set out to do, but Thermaplugg is on the run and we're closer to home than ever.", sourceObjective = "Watch the holo-table in front of High Tinker Mekkatorque to learn about Operation: Gnomeregan.", progress = "Thermaplugg's defeat is a certainty, but that irradiator has bought him time to regroup.", completion = "Even now, only the S.A.F.E. teams dare to venture far into the city to search for survivors. Meanwhile, Thermaplugg has sent one of his followers, Crushcog, to distract us and buy time for him to dig in.", sourceObjectiveStatus = "unverified-source-field" }
quests[26209] = { id = 26209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Was The Case That They Gave Me", description = "Here's the deal, kid, we've got a full-blown murder on our hands. Double homicide... Single horse... icide.\n\nWorse yet, we're in Westfall. I could throw a rock behind me and hit a dozen hobos with motive enough to want to wipe these people (and horse) out.\n\nNow I don't know who did this and I sure don't appreciate having to come to this dump to investigate the deaths of a couple of squatters, but I'll be damned if I don't find the perp. You want to help? Go talk to some bums. The hobo... knows.", sourceObjective = "Speak to the various homeless people occupying the Jansen Stead to gather clues about the Furlbrow murders.", progress = "Anything yet?", completion = "Gnolls and murlocs? Horse poopy, pal! Gnolls and murlocs didn't kill these people. I've seen what gnolls and murlocs do to people that they kill and this... isn't it. Too pretty. Too... perfect.\n\nFurthermore, the Furlbrow's had been squatting on this farm for 5 years. No, whoever wiped them out had a reason. This is murder, plain and simple and we're gonna get to the bottom of it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26210] = { id = 26210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammerita, Mon!", description = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.", sourceObjective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\n\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.", progress = "Did you get it yet?", completion = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up.", sourceObjectiveStatus = "unverified-source-field" }
quests[26211] = { id = 26211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapjaws, Mon!", description = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.\n\nDo me and the people of Revantusk Village a service and kill em, mon.\n\nKill the whole lot of em!", sourceObjective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.", completion = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[26212] = { id = 26212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lard Lost His Lunch", description = "Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.", sourceObjective = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\n\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", progress = "<Lard rubs his enormous belly.>\n\nLard so hungry.", completion = "<Lard takes the huge haunch of meat from you and stuffs it in his face.>\n\nDis hit da spot! Tanks little one.\n\nLard make you special picnic basket for help Lard.", sourceObjectiveStatus = "unverified-source-field" }
quests[26213] = { id = 26213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On the Trail: The Riverpaw Clan", description = "Seeing as how we have no other leads, we may as well chase down the information you got.\n\nThere are a couple of Riverpaw gnoll camps in the area. Track them down and search for clues. Bring back anything that you might find. Isolate your search to the Riverpaw gnolls and scouts.", sourceObjective = "Recover the Riverpaw Gnoll Clue.", progress = "Find anything on the gnolls?", completion = "Is this supposed to be some kind of joke, because I'm not laughing. Bits and pieces of red cloth? What the hell is this supposed to mean?", sourceObjectiveStatus = "unverified-source-field" }
quests[26214] = { id = 26214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On the Trail: Murlocs", description = "As pointless as I think that this is going to be, we need to investigate all of our leads.\n\nI need you to head out to the Longshore, west of here, on the coast, and shake up some murlocs. Try to find a clue or some info that can help shed some light on the murders.\n\nReturn to me if you get lucky, rookie.", sourceObjective = "Recover the Murloc Clue.", progress = "How goes the murloc hunt?", completion = "Nice find, rookie. I think I have a stack of these on my desk back at the station. We're basically back to square one. What do we know? Someone that likes to write fiction about the past sent the Furlbrows a letter.\n\nLooks like we got ourselves a real history... mystery.", sourceObjectiveStatus = "unverified-source-field" }
quests[26215] = { id = 26215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Two-Shoed Lou", description = "Looks like we got ourselves a real \"whodunit\" here, rookie. Unfortunately, it looks like the locals aren't willing to talk and the clues you got off the gnolls and murlocs are damn near worthless. We're going to have to initiate plan... be on the lookout for Two-Shoed Lou.\n\nTwo-Shoed Lou is an old confidential informant of mine who, ironically, makes his home at the Furlbrow's old pumpkin farm. Head west to the farm and find out what Lou knows.\n\nIf he gives you any guff tell him that Horatio sent you.", sourceObjective = "Speak to Two-Shoed Lou at the Furlbrow's Pumpkin Farm in Westfall.", completion = "Look, we ain't got no room for no more...\n\nHoratio sent you? Right then... um, how can I help you?\n\nHe's not here is he? Heh, he knows I wasn't hidin' from him, right? Was just tryin' to lay low and all that, ya know?", sourceObjectiveStatus = "unverified-source-field" }
quests[26219] = { id = 26219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Darkbreak Cove, a giant underwater cavern bordering the abyss.\n\nThis time we're ready. The gnomes have been engineering a beauty for us back at Stormwind, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Pincer X2 pulls up to dock beside the ship, make your way on board and help out however you can. We'll be right behind you.", sourceObjective = "Board the Pincer X2 from Voldrin's Hold and aid in securing Darkbreak Cove.", completion = "Vell done, Private {name}.\n\nThe cavern is ours, but the beast escaped. Should it raise its ugly head again, ve vill make with blastink it out of the vater.", sourceObjectiveStatus = "unverified-source-field" }
quests[26220] = { id = 26220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Is Better with Bacon", description = "Feeding a hungry orc army is never an easy task.  Luckily for us, we have a good supply of mature swine meat from the pig farms and surrounding areas south of Orgrimmar.  Do me a favor and slaughter some of those pigs for their delicious belly meat.  I will slice it up and make bacon for the troops' breakfast.", sourceObjective = "Slaughter Mature Swine south of Orgrimmar and bring me back 6 of their Swine Bellies. I will be waiting for you here in The Drag.", progress = "Have you finished slaughtering the swine?", completion = "Good work, {name}.  These will do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[26221] = { id = 26221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Tenebrous Cavern, a giant underwater cave bordering the Abyssal Breach.\n\nThis time we're ready. The goblins have been proving their worth by making a vicious machine for us back at Bilgewater Harbor, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Verne pulls up to dock beside the ship, make your way on board and find a way to make yourself useful. We'll be right behind you.", sourceObjective = "Board the Verne from The Stygian Bounty and aid in securing Tenebrous Cavern.", completion = "Well done, {class}.\n\nThat slippery beast got away! I'll be making a few upgrades. It won't be so lucky next time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26222] = { id = 26222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrounging for Parts", description = "There's just too much to do around here, and too few gnomes on their feet to help! The high tinker has asked me to start converting some of our old bots and parts from Operation: Gnomeregan. I hope to have a new line of multi-bots ready for a field test soon!\n\nI don't suppose you'd have some time to help, do you? There are all kinds of parts scattered around. Pick up anything you find and bring it back to me. You never know what could turn out to be useful!", sourceObjective = "Bring 7 Spare Parts to Engineer Grindspark in New Tinkertown.", progress = "Did you get those parts?", completion = "These are fantastic! Let's see what we can put together. Would you be interested in testing out the prototype once I'm done?", sourceObjectiveStatus = "unverified-source-field" }
quests[26223] = { id = 26223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, {race}. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", sourceObjective = "Kill 8 Silvermane Stalkers.", completion = "A job well done, {race}. The Revantusk thank you for your contribution.", sourceObjectiveStatus = "unverified-source-field" }
quests[26224] = { id = 26224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, {race}. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", sourceObjective = "Kill 10 Savage Owlbeasts.", completion = "You have proven a worthy ally to the Revantusk, {name}. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[26225] = { id = 26225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupellyverbos Port", description = "You there! Did you know that strewn across the northern beach are tens, if not hundreds, of bottles of fine wine?\n\n...well, now you do!\n\nI'd be out there gathering them by the armload, if those turtles weren't out to get me. They crave my blood, I swear.\n\nSo I'll pay you then. Bring me 12 bottles of Pupellyverbos Port and I'll \"purchase\" it from you, {class}.", sourceObjective = "Collect 12 bottles of Pupellyverbos Port.", progress = "Do you have 12 bottles? I know how to count, you know!", completion = "Perfect! I don't know where I'd get this stuff if it wasn't for drunk humans repeatedly crashing their ships.\n\nNormally I'd settle down and get ready to haggle with you for an hour, but you're in luck; I'm too eager to crack these open. Cheers!", sourceObjectiveStatus = "unverified-source-field" }
quests[26226] = { id = 26226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crawfish Creole", description = "There are a number of small lakes scattered around Orgrimmar.  These lakes fill up with crawfish every year.  That's where you come in, {name}.  I need you to catch some of those delicious crustaceans and return to me when you are done.  Assuming your catch is successful, our Horde army will feast tonight.", sourceObjective = "Catch 10 Muddy Crawfish in Orgrimmar. Deliver the crustaceans to Marogg when you are done.", progress = "Were you able to dig up some crawfish?", completion = "Ugh, I never liked cooking these slimy things.  Thanks for the help {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26227] = { id = 26227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Careful, This Fruit Bites Back", description = "Sometimes the troops want something sweet to eat.  I don't always give them what they want but this time, I am going to make an exception.  I am sure you have seen the local cactus that grows here in Orgrimmar.  These cactus produce a tasty treat called prickly pear fruit.  The trouble is the fruit are covered in spines!  Watch your hands and bring me back a handful of that fruit.", sourceObjective = "Retrieve 8 pieces of Prickly Pear Fruit. Deliver the fruit to Marogg in Orgrimmar.", progress = "Were you able to find enough fruit?", completion = "Let me see your hands... Aha!  You're not any better at collecting these wretched things than I am!", sourceObjectiveStatus = "unverified-source-field" }
quests[26228] = { id = 26228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Livin' the Life", description = "Listen, I really shouldn't be talkin' to you, but I owe Horatio a favor or two. I don't really know nothin' about what happened to the Furlbrows, but I might be able to point you in the right direction.\n\n<Lou hands you a large crate.>\n\nThat crate used to be my home before I struck it rich. Now I'm livin' the life every hobo dreams of!\n\nRight, so you take that there livin' crate and head to the Jangolode Mine, southwest of here. Head to the back of the mine and once there, hide in the crate.", sourceObjective = "Use Two-Shoed Lou's Old House at the back of the Jangolode Mine in Westfall.", progress = "Be careful with my old house. I plan to hand that off to my kids when they move out.", completion = "<Lou puts his hands to his ears and starts talking loudly.>\n\nSTOP! STOP! STOP! I don't wanna hear it! I don't wanna know and I don't care! That kind of information is liable to get you killed 'round these parts.\n\nI got one more bit of information for you and then we're done!", sourceObjectiveStatus = "unverified-source-field" }
quests[26229] = { id = 26229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"I TAKE Candle!\"", description = "Back before those damned kobolds gave me a permanent limp I used to be William Pestle's number one candle supplier. Hell, I even came up with the line \"I TAKE CANDLE!\" Yea, that was me. Kobold would say \"You no take candle!\" and I'd just respond \"I TAKE CANDLE!\" and then bash their brains in!\n\n<Jimb drifts off for a second.>\n\nGood times... The best times.\n\nNow? Can't even use the bathroom without assistance. You want to help me? Kill me some kobolds. You'll find a good load of 'em in the nearby mine.", sourceObjective = "Kill 12 Kobold Diggers.", completion = "Oh SWEET justice! Killin' those kobolds won't make me walk like a normal person and it sure won't get me a job, but damn does it feel good.\n\n<Jimb reaches into a crusty old sack.>\n\nHere, I think I got somethin' for you from my kobold huntin' days. Maybe you can put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[26230] = { id = 26230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast or Famine", description = "Life in Westfall's hard, <sonny/missy>! Every day is a struggle. We can sometimes go weeks without a decent meal. That's why it's important that we all help each other out. Maybe you can lend a hand, eh? I'm making dirt pies and need some ingredients.\n\nGet me some fresh dirt from the pumpkin patch out front and a bundle of coyote tails. You'll find coyotes wandering around in the wilds of Westfall.\n\nGet moving! We got mouths to feed.", sourceObjective = "Collect 6 Coyote Tails and 5 handfuls of Fresh Dirt.", progress = "Dirt pies don't make themselves - usually.", completion = "Just smellin' you comin' got my stomach rumblin'! We're gonna eat like kings tonight!", sourceObjectiveStatus = "unverified-source-field" }
quests[26232] = { id = 26232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lou's Parting Thoughts", description = "A couple of thugs recently showed up at the farm, causin' all kinds of trouble. I don't know where they came from or who they're working for, but I KNOW they're bad news. I may have overheard 'em talkin' 'bout subjects that might interest you.\n\nIf you're interested, you'll find the thugs back behind the farmhouse. If you get caught or killed, I don't know you. Never seen ya!\n\nGood luck, kid.", sourceObjective = "Eavesdrop on the Thugs out behind the farmhouse at Furlbrow's Pumpkin Farm in Westfall.", completion = "We're dealing with an organization here, rookie. You don't just off the richest bum in Westfall in broad daylight and leave no witnesses. Someone with a lot of power is behind these murders. What have you learned so far?", sourceObjectiveStatus = "unverified-source-field" }
quests[26233] = { id = 26233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up.", sourceObjective = "Retrieve 6 Barrels of Darkspear Rice. Deliver the rice to Marogg in Orgrimmar.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, {name}.  Don't worry, we will return the rice once we are done... or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[26234] = { id = 26234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the goblins keep it stored in barrels near their structures.  Retrieve these barrels of Kezan rice for me and I should be able to finish up.", sourceObjective = "Retrieve 6 Barrels of Kezan Rice. Deliver the rice to Marogg in Orgrimmar.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, {name}.  Don't worry, we will return the rice once we are done... or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[26235] = { id = 26235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Thieves Get Hungry", description = "We have had a problem with thieves stealing our infantry rations here in Orgrimmar for the last couple of weeks.  I recently received some intelligence of where these crimes are taking place.  Anywhere you see piles of crates and supplies, there are likely to be thieves nearby.  I need you to hunt these thieves down and recover the stolen rations.  Return to me when you are done.", sourceObjective = "Recover 3 Horde Infantry Rations. Deliver them to Marogg in Orgrimmar.", progress = "Were you able to recover the rations?", completion = "Nice work {name}!  I will see that these rations are returned to the troops immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[26236] = { id = 26236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shakedown at the Saldean's", description = "So what do we know so far? We need to follow the clues.\n\nOver at the Jansen Stead you found a water-soaked letter and some scraps of red cloth. Here at the Furlbrow's you overheard a conversation between some shadowy figure and an ogre mage. You also got a confession to the murder from a bunch of thugs - whom you then killed.\n\nSomething isn't adding up, rookie.\n\nThere's an old couple, southeast of here, at the Saldean's Farm. Head over there and speak with Farmer Saldean. Find out what he knows.", sourceObjective = "Speak with Farmer Saldean at Saldean's Farm in Westfall.", completion = "Horatio Laine? That man is a scumbag. Dirty as my underwear.\n\nListen, friend, I don't often give out advice like this, but you seem like a good man. GET OUT OF WESTFALL. You're already in way over your head. All you're doing now is putting your neck on the chopping block.", sourceObjectiveStatus = "unverified-source-field" }
quests[26237] = { id = 26237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Times are Tough", description = "Times are tough, <brother/sister>. With the downtrodden masses of Stormwind migrating into Westfall, resources are stretched as thin as they've ever been. The people are restless and in need of help.\n\nOur own farmhouse has been serving as a halfway house for years. Salma does the best that she can to keep our guests alive, but sometimes the watchers get 'em. Watchers are those twisted abominations roaming my fields - a little present left behind by the Defias, before they were driven off. Help us!", sourceObjective = "Kill 10 Harvest Watchers.", completion = "Thank you, brother. You've done Salma and I a great service and I promise that it won't soon be forgotten. I don't have much money, but you're welcome to what I do have.", sourceObjectiveStatus = "unverified-source-field" }
quests[26238] = { id = 26238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Dwarves", description = "The Horde has done much for us Revantusk, and we're no freeloaders. With the other forest troll tribes pushed back, we're striking out to claim more land in the name of the Horde.\n\nBut now the Wildhammer dwarves are getting in our way. If it's a war they want, it's a war they'll get... and I don't plan to lose a war to creatures half my height.\n\nGet out there and kill me some dwarves.", sourceObjective = "Kill 10 Wildhammer Warriors or Wildhammer Shaman.", completion = "That will show the Wildhammer to stay away from our lands!\n\nCrazy dwarves should've stayed in the mountains...", sourceObjectiveStatus = "unverified-source-field" }
quests[26240] = { id = 26240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stomp To My Beat", description = "Our warriors are out there fightin' hard to kill them nasty Wildhammer dwarves, so we can be safe back here at the village. It's only right we do what we can to support them.\n\nA good beat's what every troll needs to do his best in a fight. The poundin' rhythm of the drums drivin' you to hit harder, callin' the spirits to watch over you. Take my drums to the battlefield wit' ya. Play 'em for our warriors, and let 'em show the Wildhammer who owns these lands!", sourceObjective = "Use the Revantusk War Drums on 6 Revantusk Warriors.", completion = "Makes all the difference, doesn't it? That'll teach those dwarves a lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[26241] = { id = 26241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Stew", description = "Hello, dear. Welcome to our home. Hmm, you don't look like you're homeless. Have you come to help us? If so, you're just in time! I'm planning dinner for the young ones and need a few simple ingredients.\n\nIf you could get me some okra, goretusk flanks and stringy fleshripper meat I can make my famous Westfall stew! You'll find all of the ingredients near our farm. Just be careful of the harvest watchers. They are merciless killers.", sourceObjective = "Collect 6 Okra, 6 Stringy Fleshripper Meat and 6 Goretusk Flanks.", progress = "Food will be ready as soon as I have all of the ingredients! Hurry!", completion = "Bless your heart, dear. These poor orphans haven't had a hot meal in days.\n\nIt looks like we will have enough left over to help feed many more of the homeless of Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26243] = { id = 26243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Pillar", description = "The pillar in this room holds up more than just the Temple of Earth.\n\nThis entire plane of existence will soon collapse into our world if we fail to restore it.\n\nThe time to act will come soon, {name}.  But first you must listen to what I have to tell you.", sourceObjective = "Ask Maruut Stonebinder about the World Pillar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26244] = { id = 26244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earth Claims All", description = "We're in the plane of earth, {name}.  Everything is absorbed by the land eventually.\n\nThe Storm's Fury will soon be turned to dust and we won't be able to gain any insight from its remains.\n\nGo and destroy the elementals that are dismantling the ship.  We're only delaying the inevitable, but we need to buy ourselves some time if we're to track down all the pieces of the World Pillar.", sourceObjective = "Destroy 5 Deepstone Elementals.", completion = "You did what was necessary, {name}.  I can tell you're the sort of {class} I'll get along with well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26245] = { id = 26245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunship Down", description = "The Archstone was being transported inside a flying Horde gunship called the Storm's Fury.\n\nThe airship crashed south of here and our scrying has revealed the Archstone's no longer on it.\n\nSearch the ship for clues related to what might've happened.", sourceObjective = "Search for clues at the Storm's Fury Wreckage in Deepholm.", completion = "The clues point to an obvious conclusion.  Too obvious perhaps.", sourceObjectiveStatus = "unverified-source-field" }
quests[26246] = { id = 26246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Log", description = "<You leaf to the final, interrupted entry.>\n\n...approaching the Temple of Earth at 300 knots and commencing landing maneuvers according to new route.  We've made note of a low pressure system in the north and redrawn our...\n\nBLOOD AND THUNDER!  ALLIANCE SCUM APPROACH!!", sourceObjective = "Bring the Captain's Log to Maruut Stonebinder at the Temple of Earth in Deepholm.", completion = "Why would the Alliance attack the Horde just as they're about to deliver a fragment of the World Pillar to us?", sourceObjectiveStatus = "unverified-source-field" }
quests[26247] = { id = 26247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy First", description = "The Earthen Ring is a neutral organization, {name}.  We cannot pick sides in the war between the Horde and the Alliance.\n\nLook around you -- our members come from all backgrounds.  Our mission would be compromised should racial tensions be put above our goal.  Let's try to keep this under wraps until we have more information.\n\nWe must not jump to conclusions just yet.  I'll send you and one of our new members to look for the Alliance gunship.\n\nFind out what you can without dragging us into the conflict.", sourceObjective = "Meet Stormcaller Mylra aboard the Alliance Gunship.", completion = "Oi, {name}!  I was told I'd have company soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26248] = { id = 26248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Our Friends Are Dead", description = "Something's wrong here, {name}.\n\nThe ship's crew has been slain.  Yet there is no bloodshed or damage to the ship's structure.\n\nThis was not the Horde's doing.\n\nWe will find the answers we seek by speaking to the spirits of the dead.  They have not yet left this world.\n\nTake this totem and place it near the corpses of the fallen.  You will have a few seconds to listen to their last few thoughts.\n\nBeware, however!  There is no telling how the spirits of the dead will react to our prodding.", sourceObjective = "Use the Spirit Totem on the corpses of 6 Slain Crew Members.", progress = "The spirits always have something to say to those who will listen.", completion = "We were bound to run into the Twilight's Hammer sooner or later, {name}.  If they're behind this, it's quite likely that the World Pillar fragment is in their possession.", sourceObjectiveStatus = "unverified-source-field" }
quests[26249] = { id = 26249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral's Cabin", description = "It's possible we'll find further clues inside the admiral's cabin. You will find it directly below us.\n\nSee if there are any survivors or information that will lead us closer to the World Pillar fragment.  Be careful, {name}.  Whoever got the crew might still be out there.", sourceObjective = "Look for clues in the admiral's cabin of the Alliance Gunship.", completion = "This ship is filled with rats...", sourceObjectiveStatus = "unverified-source-field" }
quests[26250] = { id = 26250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Second Thought, Take One Prisoner", description = "It's not too late, {name}.  The cultists are probably still here.\n\nGo below decks, find out who's in charge and subdue them.\n\nWe will obtain answers to our questions, one way or another.", sourceObjective = "Subdue Mor'norokk the Hateful at the Alliance Gunship in Deepholm.", progress = "Hail, {name}.", completion = "Oi, this was a heavy one!  He nearly broke me gryphon's back!\n\nAre you ready to interrogate the ogre, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26251] = { id = 26251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take No Prisoners", description = "It looks like the Twilight's Hammer's still on the ship.  Go below decks and take them out.\n\nBe careful, {name}.  I've a feeling they're not here for a spiritual retreat, if you know what I mean.", sourceObjective = "Slay 6 Twilight Saboteurs.", progress = "Is it done, {name}?", completion = "Well done, {name}.  The Twilight's Hammer is an evil that we must fight anywhere we find them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26252] = { id = 26252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Watcher", description = "You have found what appears to be the heart of a harvest watcher.\n\nFrom the sound being emitted by the device you can tell that it's still fully functional. Perhaps you should return it to Farmer Saldean.", sourceObjective = "Return the Harvest Watcher Heart to Farmer Saldean at Saldean's Farm.", progress = "What have you got there, {name}?", completion = "Is that... Is that the heart of one of the watchers? I've heard stories about using one of these to power up a watcher for personal use. Of course I'm really in no shape to try such things myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[26254] = { id = 26254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Spraining to Do", description = "Hop on, {name}.  Let's see what Mr. Ogreface has to say for himself.\n\nDon't be shy, Stormbeak's only ever dropped a passenger a couple of times before.", sourceObjective = "Jump on Stormbeak and watch Mor'norokk's interrogation.", progress = "Yes, {name}?", completion = "We have our answers, {name}.  Let's report back.", sourceObjectiveStatus = "unverified-source-field" }
quests[26255] = { id = 26255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Temple of Earth", description = "You must get word back to the others at the temple.  Chances are, the fragment is already getting moved to a more secure location.\n\nTell Maruut what you know.  I'm going to do a little investigating about this Twilight Council in the meantime.", sourceObjective = "Speak to Maruut Stonebinder at the Temple of Earth in Deepholm.", completion = "We must investigate your findings further, but we must not lose track of the fragment.", sourceObjectiveStatus = "unverified-source-field" }
quests[26256] = { id = 26256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleed the Bloodshaper", description = "The Twilight's Hammer are wielding foul magic here, {name}.  They animate and energize the remains of Deathwing's blood, so that instead of drying out and disappearing it thrives and becomes more abundant.\n\nTake out one of the bloodshapers, see if they have any clues as to where we can find this \"forgemaster.\"", sourceObjective = "Obtain the Twilight Orders from one of the Twilight Bloodshapers at Deathwing's Fall.", progress = "We must make haste if we're to rebuild the World Pillar, {name}.", completion = "They're keeping slaves here?  We ought to free them regardless, but perhaps they might also aid us in finding the forgemaster.", sourceObjectiveStatus = "unverified-source-field" }
quests[26257] = { id = 26257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Alive!", description = "From what I've heard, all you really need to do is find a suitable harvest golem and drop in the heart. Once you've done that you should be able to take full control of the creature.\n\nI think there's a whole field of overloaded harvest golems west of here, at the Molsen Farm. Look for the arcs of electricity.\n\nShould you manage to get it working, use the golem to destroy the energized harvest reapers at the old Molsen farm. Those monsters are much more destructive than the ones on our farm.", sourceObjective = "Use the Harvest Watcher Heart on an Overloaded Harvest Golem and then use the Overloaded Harvest Golem to kill 25 Energized Harvest Reapers.", completion = "It actually worked? That's incredible, {name}. Hopefully that takes care of the harvest golem problem here in Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26258] = { id = 26258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathwing's Fall", description = "The Twilight's Hammer involvement in the disappearance of the World Pillar fragment makes complete sense.  Let us hope that we can act swiftly enough to recover it.\n\n<Maruut places his hand on your shoulder.>\n\nI've established a spiritual bond with you.  We should be able to communicate while you remain in Deepholm.\n\nGo to Deathwing's Fall to the southeast and investigate the Twilight's Hammer operation there.", sourceObjective = "Go to Deathwing's Fall in Deepholm.", progress = "Yes, {name}?", completion = "This must be where the world pillar fragment was brought.  Let's have a closer look.", sourceObjectiveStatus = "unverified-source-field" }
quests[26259] = { id = 26259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Earthwarder", description = "When Deathwing escaped to Deepholm, his corruption was extreme, but perhaps not yet absolute.\n\nThe cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power.\n\nWhat if a trace of the Earthwarder's essence remains?  After all, Neltharion was the aspect of earth before he was the aspect of death.\n\nGather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", sourceObjective = "Gather 5 samples of Blood of Neltharion from Living Blood at Deathwing's Fall.", progress = "You return, {name}.  Did you obtain the blood?", completion = "There is still great power present in his blood, {name}.  I can sense it even now.\n\nYet there is also much corruption.  I am not sure we can salvage the Earthwarder's essence from this.", sourceObjectiveStatus = "unverified-source-field" }
quests[26260] = { id = 26260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgemaster's Log", description = "Go to the tower the slave spoke of.  You should find it on the northeastern end of the camp.\n\nIf we can act fast enough we might be able to eavesdrop on the forgemaster's meeting.", sourceObjective = "Find the Forgemaster's Log at Deathwing's Fall in Deepholm.", completion = "There is an entry for an upcoming meeting at the Upper Silvermarsh.\n\nThis must be where the Forgemaster is.", sourceObjectiveStatus = "unverified-source-field" }
